'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["da"]={"g-flurpruefung":["Hvad er inkluderet i en visuel og funktionel inspektion før arbejdet påbegyndes?","Før dagens første mission.","Kontroller kun brændstofniveau og køretøjets farve.","Kontroller bremser, styretøj, gafler, dæk og sikkerhedsanordninger i henhold til betjeningsvejledningen.","Foretag en prøvetur med løftet last.","Det daglige eftersyn omfatter de sikkerhedsrelevante dele og funktioner i henhold til betjeningsvejledningen."],"g-rueckhalt":["Hvordan håndterer du det eksisterende førersikkerhedssystem?","Gaffeltrucken har et obligatorisk fastholdelsessystem.","Brug det rigtigt, mens du kører.","Brug kun på ujævne gulve.","Deaktiver den for korte ture.","De påtænkte fastholdelsesanordninger skal anvendes i overensstemmelse med fabrikantens anvisninger; de yder særlig beskyttelse i tilfælde af tiphændelser."],"g-mangelmelden":["Hvad gælder for en gaffeltruck med en beskadiget gaffel?","Når du tjekker, bemærker du en tydeligt bøjet tand.","Hvis det er muligt, fordel belastningen på den anden tand.","Kør kun lette læs indtil næste service.","Brug ikke gaffeltrucken, og rapporter fejlen til den ansvarlige person.","Beskadiget lasthåndteringsudstyr kan svigte; Sikkerhedsrelaterede defekter kræver nedlukning indtil afklaring."],"g-einweisung":["Du skifter til en gaffeltruck med forskellige styringer. Hvad kræves før brug?","Betjeningen adskiller sig fra dit tidligere køretøj.","Enhedsrelateret instruktion og overholdelse af betjeningsvejledningen.","En kort forklaring fra en uengageret kollega er altid nok.","Ingen yderligere information, hvis du har et gaffeltruckcertifikat.","En generel kvalifikation erstatter ikke den nødvendige instruktion på den faktisk anvendte enhed."],"g-anbaugeraet":["Du bør bruge en vedhæftet fil. Hvad tjekker du først?","Et nyt udstyr ændrer måden, hvorpå læsset samles op.","Om tilbehøret passer til køretøjsgodkendelsen og den tilladte belastning.","Kun om enheden kan fastgøres visuelt.","Om tilbehøret kan monteres uden dokumentation.","Tilbehør kan ændre den resterende belastningskapacitet og belastningscenter; Godkendelser og lastkapacitetsoplysninger skal kontrolleres."],"g-diagramm":["Hvorfor har du brug for belastningskapacitetsdiagrammet?","En tung belastning er til stede med tyngdepunktet langt udad.","For at bestemme den korteste rute.","For at vurdere den maksimalt tilladte belastning afhængig af løftehøjde og belastningscenter.","For at bestemme tankens kapacitet.","Tilladte belastninger afhænger blandt andet af lastmidtafstand og løftehøjde."],"g-lastschwerpunkt":["Hvad sker der typisk, når tyngdepunktet bevæger sig længere frem?","En lang last rager langt foran gaflerne.","Den tilladte bæreevne kan falde.","Bæreevnen er altid stigende.","Afstanden har ingen indflydelse på vippemomentet.","En større afstand fra lastcentret øger tipmomentet og kan reducere den tilladte lastkapacitet."],"g-gabelabstand":["Hvordan skal gaflerne hente en passende palle?","Du ønsker at hente en jævnt lastet palle.","Med tænderne så tæt som muligt og kun på det ene hjørne.","Med så stor afstand, at pallen vælter til siden.","Med passende tandafstand og tilstrækkeligt undervogns- og støtteareal.","Lasten skal understøttes sikkert og så jævnt som muligt på tværs af gaflerne."],"g-schieflast":["En last er stablet ustabilt. Hvad er rigtigt?","Papkasser kan falde ned, når de løftes.","Start langsomt; ladningen stabiliserer sig selv.","Inden lasten tages op, skal den sikres tilstrækkeligt eller få den samlet igen.","Hæv lasten over hovedhøjde, så den ikke kommer i vejen.","Løs eller ustabil last kan falde ned og bringe mennesker i fare; udføre sikkerhedsforanstaltninger først."],"g-personen":["Kan en person løftes på almindelige gafler?","En kollega vil nå et lys.","Ja, hvis kollegaen bruger hjelm.","Nej, kun anviste og tilladte faciliteter kan benyttes af personer i henhold til særlige krav.","Ja, hvis man kun nærmer sig en lille højde.","Normale gafler er ikke en personlig arbejdsplatform; Transport og løft af mennesker er underlagt særlige krav."],"g-transporthoehe":["Hvordan transporterer du normalt en palle?","Vejen er fri og jævn.","Med løftet last kun så vidt det er nødvendigt og i overensstemmelse med betjeningsvejledningen.","Med lasten løftet så højt som muligt for at blive bedre set.","Med løftemasten vippet stærkt fremad, uanset belastningen.","En lav transportposition reducerer risikoen for væltning og kollisioner; Enhedsvejledningen er afgørende."],"g-kurvenfahrt":["Hvorfor er det farligt at køre hurtigt i sving med en gaffeltruck?","Du vil hurtigt forlade en smal sti.","For det dræner bare batteriet hurtigere.","Fordi gaffeltrucken automatisk styrer bedre.","Fordi sidekræfter påvirker stabiliteten og kan føre til at vælte.","Ved kurver kommer yderligere kræfter i spil; hastigheden skal tilpasses belastningen og forholdene."],"g-ladebruecke":["Hvad tjekker du, inden du kører ind på en læssebro?","Du skal køre i en lastbil.","Bare om stien ser bred nok ud.","Lastkapacitet, sikker støtte og beskyttelse mod forskydning samt sikring af køretøjet.","Bare om belysningen er tændt.","Læssebroer og køretøjer skal være sikret mod bevægelse og egnet til lasten."],"g-fussgaenger":["Hvordan opfører du dig i et forvirrende kryds med fodgængere?","Visuelle forbindelser er begrænsede.","Kør med en passende hastighed, stop om nødvendigt og sørg for sikkert udsyn.","Gør altid krav på vigeretten, når du bærer en last.","Bare tut og fortsæt med at køre.","Fodgængere har særlige beskyttelsesbehov; Hastighed, udsyn og kommunikation skal tilpasses trafikvejen."],"g-batterieladen":["Hvad skal du være særlig opmærksom på, når du oplader et drevbatteri?","Der anvendes en batteriladestation.","Opladningsstedet kan vælges uanset producentens anvisninger.","Åben ild er tilladt, så længe lastbilen holder stille.","Egnet læsseområde, tilstrækkelig ventilation og producentens specifikationer samt brand- og eksplosionsbeskyttelse.","Ved opladning kan der opstå farer fra elektrisk energi, gasser og kemikalier; de foreskrevne beskyttelsesforanstaltninger skal overholdes."],"h-beauftragt":["Under hvilke betingelser har du lov til at betjene en arbejdsplatform selvstændigt?","Du bør bruge en arbejdsplatform i virksomheden.","Hvis du har kørekort til bil.","Hvis du er egnet, instrueret eller kvalificeret og bestilt af arbejdsgiveren.","Hvis du nogensinde har set en arbejdsplatform.","Arbejdsgiveren skal sikre egnethed, kvalifikationer og opgaver i overensstemmelse med driftskrav."],"h-vorpruefung":["Hvad skal kontrolleres, før arbejdet påbegyndes med liften?","Scenen stod udenfor natten over.","Visuel og funktionel test i henhold til producentens instruktioner inklusive sikkerhedsanordninger.","Kun scenens farve og alder.","Om arbejdsmaterialet allerede er på platformen.","Før brug skal maskinen, betjeningselementer, nødfunktioner og synlige skader kontrolleres i henhold til betjeningsvejledningen."],"h-tragfaehigkeit":["Hvilke oplysninger bestemmer den tilladte belastning af arbejdskurven?","To personer vil gerne have ekstra værktøj med.","Folk kan frit anslå den tilladte totalvægt.","Kun vægten af ​​den tungeste person tæller.","Bæreevnespecifikationen for personer, værktøj og materialer må ikke overskrides.","Den nominelle belastning refererer til den samlede tilladte belastning, inklusive eventuelt transporteret materiale."],"h-untergrund":["Hvad overvejer du, før du sætter en scene op med støtter?","Du arbejder i nærheden af ​​et fyldt område.","Kun inden for bommens rækkevidde.","Kontroller undergrundens bæreevne og jævnhed samt passende understøtning i henhold til instruktionerne.","På det lavest mulige antal udvidede understøtninger.","Utilstrækkelig jord eller forkert støtte kan føre til tab af stabilitet."],"h-wind":["Stærk vind sætter ind. Hvordan gør du det?","Du finder dig selv med en udendørs scene.","Overhold producentens grænser, og hvis de overskrides, skal du stoppe driften eller sænke kurven sikkert.","Forlæng platformen så langt som muligt, så den er mere stabil.","Reager kun, hvis løse genstande falder ned.","Vindforholdene tilladt af producenten er grænser for brug; Vind kan skabe farlige yderligere kræfter."],"h-strom":["Du skal arbejde i nærheden af ​​en luftledning. Hvad er afgørende?","En strømførende linje er i arbejdsområdet.","En hjelm erstatter at holde en sikker afstand.","Bare isoler kurven og arbejd uden koordination.","Afklar fareområdet og sørg for nødvendige beskyttelsesafstande eller andre egnede foranstaltninger.","Elektrisk flashover er også muligt uden direkte kontakt; Nødvendige beskyttelsesforanstaltninger skal fastlægges før påbegyndelse af operationen."],"h-notablass":["Hvorfor skal nødsænkningsproceduren kendes?","En fejl i den normale kontrol er mulig.","Så i tilfælde af fejl er sikker redning mulig i henhold til enheden.","Så enheden kører hurtigere ved normal drift.","For at erstatte almindelig test.","Nødstyringer, nødsænknings- og redningskoncepter skal være kendte og funktionelle før brug."],"h-gelaender":["Hvordan opnår du ekstra højde i arbejdskurven?","Et montagepunkt er lige uden for din rækkevidde.","Klatre op på kurvehegnet.","Placer et bræt på rækværket.","Brug en passende platform med tilstrækkelig arbejdshøjde; klatre ikke på rækværk.","Klatring af hegnet eller improviserede forhøjninger bringer faldsikringen i fare."],"h-psaga":["Hvilke krav gælder for personligt faldsikringsudstyr?","Du bruger en arbejdsplatform, hvortil der leveres et fastspændingssystem.","Ethvert forankringspunkt uden for kurven er altid tilstrækkeligt.","Overhold risikovurdering, fabrikantoplysninger og passende forankringspunkter.","Brug ikke nogen sikkerhed, hvis kurven har et rækværk.","Hvorvidt og hvilket PPE der er nødvendigt, afgøres af risikovurderingen, sceneopbygningen og driftsvejledningen."],"h-verfahren":["Kan scenen flyttes med platformen hævet?","Arbejdspladsen ligger få meter væk.","Kun hvis modellen og driftsforholdene tillader det i henhold til producentens anvisninger.","Altid, så længe alle holder fast.","Nej, aldrig uanset design og producentens godkendelse.","Bevægelsen i hævet position afhænger af apparatet og er kun tilladt inden for de godkendte driftsbetingelser."],"h-kollision":["Hvad skal organiseres, når man arbejder i nærheden af ​​kraner eller andre maskiner?","Bevægelige dele kan nå arbejdskurven.","Intet; arbejdskurven er altid synlig.","Kør altid arbejdskurven hen over de andre maskiner.","Koordiner arbejdsområder for at undgå kollisioner eller klemmepunkter.","Samtidig maskindrift kræver koordinerede arbejdsprocesser og beskyttelse mod kollisioner eller blokering."],"h-einstieg":["Hvordan kommer du ind i eller forlader arbejdskurven?","Du når kurven i jordhøjde.","Klatre over det udvendige rækværk.","Via den tilsigtede adgang i en sikker position i henhold til betjeningsvejledningen.","Via en stige placeret ved siden af ​​med bommen udstrakt.","Tilsigtet adgang og fabrikantens instruktioner skal overholdes; Ukontrolleret klatring over udgør en risiko for at falde."],"h-defekt":["Nødstop-faciliteten fungerer ikke. Hvad laver du?","Du vil opdage fejlen under inspektionen.","Brug ikke platformen og anmeld defekten.","Fortsæt med at arbejde, hvis normale kontroller virker.","Tape kontakten, så ingen betjener den.","Fejl i en sikkerhedsanordning er en sikkerhedsrelevant defekt og forhindrer sikker drift."],"h-sicht":["Kørebevægelsen kan ikke ses på grund af en forhindring. Hvordan griber du det an?","Du bør flytte en mobil scene.","Kør langsomt uden udsyn.","Bare stol på afstandsindikatoren.","Stop bevægelsen og sørg for udsyn eller sikker instruktion i henhold til betjeningsvejledningen.","Før proceduren skal personer, forhindringer og færdselsveje overvåges sikkert."],"h-rettung":["Hvad indebærer implementeringsplanlægning, når du arbejder i større højder?","Scenen bruges i et fjerntliggende område.","Kun den planlagte arbejdstid.","Et passende redningskoncept med tilgængelige, uddannede personer og nødsænkningsprocedurer.","Den antagelse, at brandvæsenet vil løse ethvert problem med det samme.","En effektiv redning skal tilrettelægges på forhånd, selvom den normale kontrol svigter."],"k-befaehigung":["Hvad kræves der for at betjene en kran selvstændigt?","Det er meningen, at en ny medarbejder skal overtage kranarbejdet.","Egnethed og nødvendige kvalifikationer, instruktion og tilhørende opgave.","Et bilkørekort er tilstrækkeligt.","At se én gang er nok.","Kranarbejde må kun overdrages til kvalificerede og autoriserede personer; Udstyrsinstruktion er en del af det."],"k-funktionspruefung":["Hvad skal der til for at tjekke kranen inden skiftet starter?","Du overtager en indendørskran.","Læs blot køretiden på typeskiltet.","Kontrollér sikkerhedsrelevante funktioner og synlige mangler i henhold til betjeningsvejledningen.","Test kranen med maksimal belastning uden kontrol.","Den obligatoriske driftskontrol tjener til at identificere farlige fejl på et tidligt tidspunkt."],"k-traglast":["Hvad er betydningen af ​​den tilladte bæreevne?","En byrde skal løftes.","Det er en uforpligtende anbefaling.","Det gælder kun, når krogen er trukket helt ind.","Den tilladte belastningsevne for den pågældende driftstilstand må ikke overskrides.","Tilladte belastninger for visse typer kraner kan afhænge af radius, bomposition og bevæbning."],"k-personen":["Hvad gælder for personer under hængende last?","Byrden flyttes over et arbejdsområde.","Fareområdet skal holdes frit; ingen må træde under den ophængte last.","En hjelm giver dig mulighed for at blive direkte under den.","Korte krydser er tilladt, hvis kranen bevæger sig langsomt.","Ophængte laster udgør en risiko for fald og klemning; Personer skal holdes væk fra fareområdet."],"k-signale":["Man kan ikke se angriberen, og man får modstridende signaler. Hvad laver du?","Kommunikationen er uklar.","Fortsæt den sidste kørekommando.","Stop bevægelsen og tydeliggør kommunikationen.","Sæt lasten ned hurtigere uden konsultation.","Sikre lastbevægelser kræver klare signaler og klar kommunikation."],"k-sicht":["Hvem yder support under transporten, hvis kranføreren ikke helt kan se lastvejen?","En hal-søjle skjuler stien.","En person, der tilfældigvis kommer forbi uden forudgående aftale.","Ingen; kun krogen er vigtig.","En passende, instrueret person med klart aftalt forståelse.","Hvis lastvejen ikke er synlig, kræves passende instruktion eller en anden sikker løsning."],"k-ruck":["Hvorfor skal rykkende kranbevægelser undgås?","En tung last begynder at svinge.","De skaber yderligere dynamiske belastninger og kan destabilisere belastningen.","De reducerer stort set enhver pendulbevægelse.","De øger altid den nominelle belastningskapacitet.","Accelerations- og bremsekræfter øger belastningen af ​​kran og slynger."],"k-sperrbereich":["Hvad skal du tjekke, før du svinger en last i et fælles område?","Andre medarbejdere arbejder i nærheden.","Om belastningen visuelt matcher kranen.","Om fareområdet er sikret, og ingen personer er i fare.","Om byrden kan bæres så højt som muligt over alle.","Dreje- og læssevejene skal være fri for ubeskyttede personer."],"k-stuetzen":["Hvad er afgørende for en mobilkran med støtteben?","En kran opsættes på delvist fyldt jord.","Kun vejens bredde.","Farven på støttepladerne.","Bærende underlag samt støtte og lastfordeling iht. monterings- og producentanvisninger.","Installationen har en væsentlig indflydelse på stabiliteten, især ved skiftende jordforhold."],"k-wetter":["Et vindstød får lasten til at svaje betydeligt. Hvad er rigtigt?","Du arbejder udendørs.","Stop bevægelsen sikkert og overhold tilladte driftsbetingelser.","Fremskynd bevægelsen hurtigt.","Fortsæt med at løfte lasten på trods af overskridelse af producentens grænser.","Vind og svajende bevægelser kan destabilisere lasten og kranen; Ansøgningsgrænser skal overholdes."],"k-freileitung":["Hvad gælder ved brug af kraner i nærheden af ​​elektriske luftledninger?","Bom eller last kan nærme sig linjen.","Med en ikke-ledende belastning er afstande ligegyldige.","Afklar fareområdet og nødvendige beskyttelsesforanstaltninger med de ansvarlige inden arbejdet påbegyndes.","Stol kun på kranførerens egen reaktion.","Der er farer ved kontakt og spændingsoverslag; sikre beskyttelsesafstande eller andre foranstaltninger er påkrævet."],"k-sichern":["Hvad gør du, før du forlader kranen?","Arbejdet afbrydes.","Lad lasten hænge ophængt.","Lad kranen være uden opsyn med drevet kørende.","Sænk lasten sikkert og fastgør kranen i henhold til betjeningsvejledningen.","Ophængte laster må ikke efterlades ukontrollerede; Kran og last skal parkeres sikkert."],"k-lastanschlag":["Hvordan ved man, om den anvendte sejl er egnet?","Byrden skal løftes ved hjælp af en løftestrop.","Med hensyn til mærkning, belastningsevne, tilstand og egnethed til påbygningstypen.","Bare ved farven på løfteremmen.","For den blev allerede brugt i går.","Belastningsevne og tilstand skal være tilstrækkelig under hensyntagen til fastgørelsesforholdene."],"k-stopp":["En person kommer uventet ind i lastbanen. Hvad laver du?","Kranen flytter i øjeblikket et læs.","Stop bevægelsen sikkert øjeblikkeligt og få ryddet fareområdet.","Bare giv et advarselssignal og fortsæt med at køre.","Hæv lasten højere og kør over den.","Mennesker skal beskyttes mod lastbevægelser; Hvis der er en umiddelbar fare, skal bevægelsen standses."],"k-neuerkran":["Du vil modtage en kran med en ukendt kontrol. Hvad er rigtigt?","Kontrollerne er anderledes end før.","Prøv de sædvanlige nøgler, hvis du har mistanke.","Tillad en anden uden træning at køre videre.","Modtag den nødvendige enhedsrelaterede instruktion før uafhængig brug.","Selv erfarne kranførere har brug for viden om de specifikke styringer, der anvendes, beskyttelsesanordninger og begrænsninger."],"a-kennzeichnung":["Hvordan ved man den tilladte bæreevne for en sejl?","Du vil vælge en slynge.","Duften af ​​materialet.","På den relevante, læselige bæreevnemærkning og fabrikantens oplysninger.","Om længden af ​​opbevaringstiden.","Den tilladte bæreevne bestemmes af mærkning og driftsbetingelser."],"a-sichtpruefung":["Du bemærker et tydeligt snit i løftestroppen. Hvordan griber du det an?","Bandet skal bære en last.","Brug ikke båndet og send det til test eller afvisning.","Dæk snittet med tape.","Brug den kun til særligt lette belastninger.","Beskadigede tekstilslynger kan svigte og skal vurderes efter kasseringskriterierne."],"a-neigungswinkel":["Hvad sker der, hvis hældningsvinklen på slyngestrengene er større end lodret?","En to-strenget bøjle breder sig mere ud.","Trådkræfterne aftager altid.","Trådkræfterne forbliver de samme.","Kræfterne i trådene øges; Tilladte vinkler og belastningsevner skal overholdes.","Når spredningen øges, øges trækkraften pr. støttestreng."],"a-schwerpunkt":["Hvorfor skal du kende lastens tyngdepunkt?","Belastningen er bygget ujævnt op.","Så lasten forbliver stabil, når den løftes og ikke vælter ukontrolleret.","For at vælge farven på sejlene.","Så lasten kan drejes hurtigere.","Ugunstige fastgørelsespunkter eller placeringen af ​​tyngdepunktet kan føre til væltning, skridning eller skråninger."],"a-kantenschutz":["En løftestrop ligger mod en skarp komponentkant. Hvad skal der gøres?","Komponenten skal løftes.","Løft lasten hurtigt, før selen beskadiges.","Brug egnet kantbeskyttelse og tjek typen af ​​fastgørelse.","Rengør kun lastoverfladen med en klud.","Skarpe kanter kan beskadige støttefibre; slyngeudstyret skal beskyttes tilsvarende."],"a-haken":["Hvad er du opmærksom på, når du sætter en sejl på?","Du bruger en lastkrog.","Placer sejlet på siden af ​​krogspidsen.","Hold sikkerhedsklappen åben permanent.","Læg krogen som beregnet i krogens bund og observer sikkerhedsanordninger.","Utilladt belastning på spidsen af ​​krogen og manglende sikring kan føre til, at den afkroges."],"a-knoten":["Kan man forkorte en løftestrop, der er for lang med en knude?","Stoplængden passer ikke.","Ingen; Brug kun en egnet, godkendt sejltype eller egnet løfteudstyr.","Ja, hvis knuden trækkes meget stramt.","Ja, så længe lasten i øjeblikket er stationær.","Knuder kan svække tekstilslynger væsentligt og er ikke tilladt improviserede længdejusteringer."],"a-probehub":["Hvorfor løftes en byrde forsigtigt i starten?","Du ønsker at transportere sikkert.","Så hun kan pendle hurtigst muligt.","For at kontrollere sejlens position, stabilitet og tyngdepunkt.","Fordi belastningskapaciteten øges automatisk.","Et kontrolleret første slag hjælper med at opdage forkerte stop og ustabile lastpositioner."],"a-lastweg":["Hvor må folk opholde sig, mens læsset transporteres?","Lasten flyttes med kran.","Direkte under belastningen med en beskyttelseshjelm.","På byrden, hvis de kan holde.","Uden for fareområdet og ikke under hængende last.","Selv med omhyggelig fastgørelse er der stadig farer ved faldende eller svingende laster."],"a-haende":["Hvordan undgår du klemskader ved fravænning?","Belastningen nærmer sig støttefladen.","Hold hænder og fødder væk fra knuseområdet og brug passende hjælpemidler.","Hold læsset med din bare hånd.","Stå mellem lasten og væggen for at rette positionen.","Der opstår farlige klempunkter mellem lasten og støtten."],"a-vierstraenge":["Hvad gælder for belastningsfordeling på et firebensophæng uden belastningskompensation?","En stiv last er fastgjort.","Alle fire tråde bærer uundgåeligt samme mængde.","Uden bevis for ensartet fordeling må bæreevnen ikke anvendes som et generelt skøn for fire ligeligt belastede tråde.","Hældningsvinklen er da irrelevant.","Ulige strengbelastning er mulig med stive belastninger; Konstruktionen og den tilladte belastningsevne skal tage højde for dette."],"a-chemikalien":["Hvad gælder ved brug af tekstilslynger i kontakt med kemikalier?","Du arbejder med en ukendt væske.","Farven på båndet viser pålideligt dets holdbarhed.","Hvert tekstilbånd er modstandsdygtigt over for alle kemikalier.","Tjek holdbarhed og producentoplysninger; Brug ikke uegnede midler.","Kemikalier kan angribe sejl og ubemærket reducere deres bæreevne."],"a-aufbewahrung":["Hvordan opbevares sejl efter brug?","Missionen er forbi.","Rens, tør og beskyttet mod skader i henhold til producentens specifikationer.","Sidder fast på jorden under en ubeskyttet belastning.","På enhver skarp udendørs krog.","Passende opbevaring forhindrer for tidligt slid og gør visuel inspektion lettere."],"a-auswahl":["Hvad skal du være særligt opmærksom på, når du håndterer følsomme eller skarpkantede belastninger?","En malet maskinkomponent skal flyttes.","Kun transporthastigheden.","Egnede sejl og beskyttelsesforanstaltninger til lastoverfladen og kanterne.","Uanset belastning, altid det samme stålkabel.","Type af fastgørelse og materiale skal matche geometri, overflade og fare."],"a-abstimmung":["Kranføreren har intet udsyn til dig. Hvordan giver du instruktioner?","Du er tildelt som angriber.","Du vinker efter behag, indtil en bevægelse begynder.","Du ringer bare et enkelt og går væk.","Via tydeligt aftalte skilte eller anden pålidelig kommunikation.","Angribere og kranførere skal kommunikere tydeligt; Hvis det er uklart, skal bevægelsen standses."],"b-qualifikation":["Hvad har en person brug for for sikkert at betjene en hydraulisk gravemaskine under drift?","En ny person bør overtage byggepladsarbejdet.","Passende kvalifikationer, enhedsrelateret instruktion og påkrævet opgave.","Kun et bilkørekort.","Bare en hurtig observation af operationen.","Arbejdsgiveren skal sikre de nødvendige kvalifikationer og instruere operatøren hensigtsmæssigt til opgaven."],"b-pruefung":["Hvad er inkluderet i det daglige maskineftersyn?","Du overtager en gravemaskine.","Tjek malingsfarven og sædebetræk.","Visuel inspektion og funktionstest i henhold til betjeningsvejledningen, for eksempel for utætheder og skader.","Bevæg bommen med fuld hastighed, indtil den stopper.","Beskadigelse af hydraulik, chassis og sikkerhedsanordninger kan føre til alvorlige ulykker."],"b-leitungen":["Hvad skal man vide om underjordiske rør før udgravning?","Du burde grave en grøft.","Kun den omtrentlige dybde af den planlagte gravegrav.","Farven på de overjordiske markeringer er tilstrækkelig.","Afklar placeringen af ​​mulige linjer og fastlæg passende sikkerheds- og efterforskningsforanstaltninger.","El-, gas- eller vandrør kan have livsfarlige konsekvenser, hvis de bliver beskadiget."],"b-schwenkbereich":["Hvordan beskytter man folk i gravemaskinens svingområde?","Du samler materiale op med bommen.","Afspær eller sikre fareområdet og hold personer væk.","Før du drejer, flyttes skovlen langsomt.","Kør over området over hovederne.","Drejelig overbygning og arbejdsudstyr skaber fare for knusning og stød."],"b-boeschung":["Hvad er vigtigt, når man arbejder tæt på kanten af ​​en gravegrav?","Gravemaskinen står på etableret eller fyldt jord.","Alene gravedybden bestemmer den tilladte placering.","Vær opmærksom på bæreevnen og sikringen af ​​kanten samt de nødvendige afstande ifølge risikovurderingen.","Kør så tæt på kanten som muligt for at spare rækkevidde.","Hvis der er utilstrækkelig frihøjde eller stabilt underlag, kan volden svigte, og maskinen kan falde."],"b-standsicherheit":["Hvorfor er hældning og jord afgørende for brug?","Byggepladsen ligger på en skråning.","Maskinen er lige så stabil på enhver overflade.","Bælteundervogne eliminerer enhver risiko for at vælte.","Ujævnheder og skråninger kan påvirke stabiliteten; Overhold anvendelsesgrænser.","Stabiliteten og tipsikkerheden afhænger af gulv, udstyr, last og maskinposition."],"b-wechselgeraet":["Hvad kontrollerer du efter at have skiftet en gravemaskineskovl med en lynkobling?","En ny vedhæftet fil blev installeret.","Om den er korrekt låst og sikret i henhold til betjeningsvejledningen.","Bare om skovlens farve passer.","Om hydraulikken arbejder så stille som muligt.","Defekte låse kan få tilbehør til at falde."],"b-heben":["Hvad skal du være opmærksom på, når du løfter et frithængende læs med en gravemaskine?","Gravemaskinen bruges til løfteoperationer.","Kun den sædvanlige gravekraft er afgørende.","Overhold den tilladte løftelast, egnede fastgørelsespunkter og foreskrevne beskyttelsesanordninger.","Lasten kan hægtes på skovlens tænder.","Løft er kun tilladt under de tilsigtede driftsforhold med egnet udstyr."],"b-rueckwaerts":["Man skal bakke, men man kan ikke se stien. Hvad er rigtigt?","Andre arbejdere er i nærheden.","Kør forsigtigt af sted uden udsyn.","Bare tut og fortsæt med at køre.","Stop, sørg for udsyn og fareområdet eller organiser passende instruktioner.","Bakning må ikke bringe mennesker i fare; begrænset sigtbarhed kræver yderligere foranstaltninger."],"b-kabel":["Bommen kan komme tæt på en luftledning. Hvad laver du?","Du arbejder på en trang byggeplads.","Afklar på forhånd fareområdet og passende beskyttelsesforanstaltninger med de ansvarlige.","Ignorer linjen, hvis bommen er malet.","Bevæg kun bommen særligt hurtigt.","Elektriske farer opstår ved kontakt og overslag; sikre afstande og beskyttelsesforanstaltninger er nødvendige."],"b-verlassen":["Hvordan parkerer du gravemaskinen, inden du tager af sted?","Du tager en pause.","Lad bommen flyde frit.","Sæt arbejdsudstyret sikkert ned og sikre maskinen mod bevægelse og uautoriseret brug.","Lad motoren køre og kabinen stå åben.","Sænket arbejdsudstyr og beskyttelse mod utilsigtet bevægelse reducerer risikoen for ulykker."],"b-hydraulik":["Du bemærker hydraulikolie under højt tryk på en beskadiget ledning. Hvad er rigtigt?","En ledning lækker.","Mærk lækagen med hånden.","Monter en ny klemme under tryk.","Sluk maskinen sikkert, lad trykket reduceres, og sørg for, at reparationer udføres af autoriseret fagpersonale.","Hydraulikvæske under højt tryk kan forårsage alvorlige skader; kontroller aldrig for utætheder i hånden."],"b-unterbau":["Hvad er faren ved at køre på ustabile overflader?","Jorden er blød efter regn.","Maskinen kan synke, glide eller vælte.","Drevet bliver automatisk bredere.","Dette gør drejeområdet mere sikkert.","Utilstrækkelig lasteevne kan forringe stabiliteten og køresikkerheden betydeligt."],"b-arbeitsgeraet":["Kan nogen arbejde under et hævet redskab?","En person ønsker at kontrollere noget under skovlen.","Ja, når motoren går i tomgang.","Nej, ikke uden den nødvendige sikre støtte og sikring af arbejdsudstyret.","Ja, hvis personen har sikkerhedshjelm på.","Hydraulisk udstyr kan synke; Vedligeholdelsesarbejde kræver sikkert arbejdsudstyr."],"b-geraeteart":["Du skifter fra en hydraulisk gravemaskine til en hjullæsser. Hvad kræves der?","Drift og bevægelsesadfærd er forskellig.","Bare det samme fodtøj.","En prøvetur uden instruktioner.","Den kvalifikation eller instruktion, der kræves for den nye maskintype.","Kvalifikationen skal matche den anvendte type maskine og de specifikke driftskrav."],"g-neigung":["Du kører en lastet gaffeltruck på en skråning. Hvad er vigtigt?","Ruten har en tydelig gradient.","Før altid lasten ned ad bakke, selvom den er tung.","Før lasten op ad bakke, og overhold de driftsmæssige retningslinjer for kørsel på skråninger.","Uanset kørselsretningen hæves gaffelen til det maksimale.","På stigninger og nedkørsler skal lasten altid føres op ad bakke; Køretøjet og betjeningsvejledningen skal overholdes."],"g-gabelabsenken":["Hvorfor skal gaflen sænkes ved parkering?","Gaffeltrucken er parkeret til en pause.","Så andre kan bruge gaflen til at klatre op.","Så gaflen forbliver mere synlig på afstand.","For at løfte lasten ikke udgør en unødig risiko for at snuble eller komme til skade.","Sænkede lasthåndteringsanordninger reducerer risikoen for ulykker på grund af fremspringende eller usikrede gafler."],"g-fahrerwechsel":["En kollega vil gerne låne gaffeltrucken. Hvad skal være til stede?","Kollegaen har kun mundtlig tilladelse fra dig.","Han skal have de nødvendige kvalifikationer og et operationelt mandat.","Din egen opgave gælder automatisk også for ham.","Et privat bilkørekort er tilstrækkeligt for enhver virksomhed.","Uafhængig ledelse er knyttet til personlig egnethed, uddannelse, kvalifikationer og operationelle opgaver."],"g-ladungssicherung":["En palle indeholder løse, stablede kasser. Hvad er rigtigt?","En papkasse kan falde ned under kørslen.","Sikre lasten mod at glide og falde før transport.","Kør kun langsomt på særligt ujævnt underlag.","Kompenser for løse kasser med en højere gaffelposition.","Lasten skal være stabil og sikret mod at falde, før den transporteres med industritrucken."],"g-bodenbelastung":["Foran dig ligger et tæppe med begrænset bæreevne. Hvordan beslutter du dig?","Ruten fører over et mellemniveau.","Vær bare opmærksom på vægten af ​​lastbilen uden last.","Afklar den tilladte gulvbelastning for gaffeltrucks og laster.","Kør med momentum, så loftet er under belastning i kortere tid.","Det relevante er den samlede faktiske belastning af området, herunder køretøj, last og dynamiske påvirkninger."],"g-verkehrswege":["En afmærket gangsti krydser din sti. Hvad er rigtigt?","Fodgængere kan til enhver tid tilgå krydset.","Du kan altid gøre krav på prioritet med hornet.","Det er tilladt at køre over afmærkningen uden at blive observeret.","Tilpas din hastighed, vær opmærksom på fodgængere og fortsæt kun at køre, når stien er fri.","Trafikveje skal køres med hensyn til mennesker; Advarselsskilte erstatter ikke sikker udsyn og fri rute."],"g-parkbremse":["Du parkerer en gaffeltruck på jævnt underlag. Hvad omfatter det?","Du ønsker at forlade førersædet i flere minutter.","Parker, træk parkeringsbremsen og sikre mod uautoriseret brug.","Lad kun køretøjet stå i neutral position.","Lad gaflen stå i hovedhøjde, så ingen rører den.","Før afgang skal trucken standses sikkert og sikres mod utilsigtet bevægelse."],"g-typenschild":["Hvilke oplysninger er bindende, når det kommer til lasten på en gaffeltruck?","Du vil hente en tung maskine.","Den estimerede lasteevne baseret på køretøjets størrelse.","Producentens oplysninger i belastnings- eller belastningsdiagrammet.","Vægten af ​​den sidst transporterede palle.","Den tilladte last bestemmes af producentens oplysninger og afhænger blandt andet af lastcenter og løftehøjde."],"g-tore":["Du nærmer dig en lav passage med en gaffeltruck. Hvad tjekker du?","Der er en tårnhøj last på køretøjet.","Om passage inklusive last og fastgørelse er mulig sikkert.","Kun højden på gaffelslæden uden last.","Om du kan køre hurtigere igennem, før porten lukker.","Før passager skal der tages hensyn til den frie højde og bredde samt dimensioner af last og køretøj."],"g-reifen":["Under dit daglige tjek finder du et stærkt beskadiget dæk. Hvad laver du?","Sikkerhedsrelevante skader er synlige på dækket.","Du kører langsomt indtil din almindelige vedligeholdelsesaftale.","Du øger dæktrykket og fortsætter med at køre.","Du tager ikke køretøjet i drift og anmelder skaden.","Beskadigede dæk kan forringe stabilitet og håndtering; fejlen skal afklares inden brug."],"h-absperren":["Medarbejdere går forbi under din arbejdsplatform. Hvad er nødvendigt?","Der er fare ved faldende værktøj.","Et passende beskyttende eller begrænset område under arbejdspladsen.","Bare en besked når du først går forbi.","Opbevar værktøj så langt væk fra kanten af ​​kurven som muligt.","Et arbejdsområde under forhøjede arbejdsstationer skal sikres mod fare fra faldende dele."],"h-werkzeuge":["Hvordan transporterer du værktøj i arbejdskurven?","Der skal flere små værktøjer til i højden.","Placer dem løst på rækværket, så de er inden for rækkevidde.","Opbevar og fastgør dem på en sådan måde, at de ikke falder ned eller hindrer driften.","Sæt fast på ydersiden af ​​rækværket i lommen.","Løse genstande kan falde ned og bringe mennesker i fare; sikker opbevaring er påkrævet."],"h-abstuetzung":["En støtte står på et brønddæksel. Hvad skal tjekkes?","Du vil hæve platformen.","Bare sørg for, at låget er tørt.","Om belastningen kan optages sikkert på det tidspunkt.","Om de andre understøtninger ikke skal bruges.","Undergrunden og kontaktarealerne skal sikkert kunne optage de understøttende kræfter; Omslag skal vurderes særskilt."],"h-notaus":["Hvornår skal nødstopanordningen bruges?","En farlig bevægelse opstår straks.","Først i slutningen af ​​en almindelig vagt.","Til standsning i akut fare i henhold til betjeningsvejledningen.","Som erstatning for den planlagte sænkning.","Nødstoppet bruges til at afværge fare, ikke den sædvanlige kontrol eller normal nedlukning."],"h-schraegstellung":["Scenehældningsadvarslen reagerer. Hvordan reagerer du?","Maskinen står på en skrå overflade.","Du ignorerer advarslen ved lave arbejdshøjder.","På trods af advarslen kører du til højeste løfteposition.","Du stopper og bringer scenen i sikker stand i henhold til producentens anvisninger.","Vippeadvarsler kan indikere utilstrækkelig stabilitet; yderligere bevægelser må ikke øge faren."],"h-umgebung":["Hvad skal organiseres, når man etablerer sig i nærheden af ​​et trafikområde?","Køretøjer kan røre scenen.","Beskyttelse mod kollisioner og passende trafikvejledning.","Sving arbejdskurven så langt som muligt over vejen.","Bare et advarselsopkald før du starter op.","Arbejdsplatforme skal beskyttes mod kollisioner med trafikanter; installationen skal sikres i overensstemmelse hermed."],"h-ueberlast":["Overbelastningsadvarslen i kurven udløses. Hvad laver du?","Yderligere værktøjer blev inviteret.","Afslut arbejdet med højere hastighed.","Angiv den tilladte kurvebelastning og følg producentens anvisninger.","Sluk for advarselssignalet permanent.","Den maksimalt tilladte belastning af kurven, inklusive personer og materiel, må ikke overskrides."],"h-quetschen":["Du kører kurven tæt under et tag. Hvilken fare er særlig vigtig?","Der er lidt plads tilbage over kurven.","Fastspænding eller knusning mellem kurven og strukturen.","At motoren bruger mere brændstof.","At køreretningen altid vender automatisk.","Snævre pladser over eller ved siden af ​​arbejdskurven kan forårsage alvorlige klemskader."],"h-stromausfall":["Scenen forbliver i stor højde uden hoveddrev. Hvad er rigtigt?","Den normale kurvekontrol reagerer ikke længere.","Du kravler ned af bommen uden sikkerhed.","Du venter til slutningen af ​​din vagt uden at blive informeret.","Påbegynd den forberedte redning ved hjælp af uddannede personer og nødsænkning.","Sikker redning skal planlægges for forstyrrelser; Uddannede personer skal kende nødfunktioner."],"h-transportstellung":["Hvordan sætter du scenen for en transport?","Arbejdsplatformen læsses på et egnet køretøj.","Bring bommen og platformen i transportstilling i henhold til betjeningsvejledningen.","Bind platformen så langt ud som muligt.","Lad støtterne være forlænget, så det fylder mere.","Den foreskrevne transportposition og lastsikring er baseret på producenten og transportspecifikationerne."],"k-bremsprobe":["Hvad viser en funktionstest af kranbremsen før brug?","Du vil gerne være i stand til at holde en last sikkert.","Om bremsen stopper og holder bevægelsen efter hensigten.","Bare om kabinebelysningen virker.","Om krogen automatisk kan holde en last.","Før brug skal sikkerhedsrelevante funktioner kontrolleres i henhold til specifikationerne."],"k-schraegzug":["Kan du trække en sidelæns byrde på skrå med kranen?","Krogen er ikke lodret over lasten.","Ja, hvis kranen stadig har lastreserve.","Nej, byrder må ikke trækkes med utilladelige diagonale træk.","Ja, hvis slyngene er særligt korte.","Diagonal træk kan forårsage ukontrollerede bevægelser og yderligere belastning af kran og slynger."],"k-verhakt":["Der hænger en last på underkonstruktionen. Hvad er rigtigt?","Modstand mærkes ved løft.","Du bliver ved med at løfte, indtil det kommer væk.","Du flytter lasten sidelæns i ryk.","Du stopper og får fjernet fastgørelsen eller blokeringen sikkert.","Fastsiddende last må ikke rives løs med magt, da der kan opstå uacceptable kræfter."],"k-anzuheben":["Hvad tjekker du, når du kortvarigt løfter en ophængt last for første gang?","Lasten løfter sig et par centimeter fra jorden.","Om den hænger i balance og stoppet er sikkert.","Om en person kan sætte sig selv direkte under byrden.","Om kranen bliver mere stabil ved at dreje hurtigt.","Korte kontrollerede løft bruges til at kontrollere fastgørelse, balance og sikker lastadfærd."],"k-lastweg":["Hvor skal transportvejen for en kranlast være?","Flere arbejdspladser er under den mulige belastningsvej.","Hvis det er muligt, over besatte arbejdsstationer.","På en planlagt, fri sti uden mennesker i fare.","Altid diagonalt gennem det travleste område.","Lastruter skal tilrettelægges på en sådan måde, at personer ikke udsættes for fare af hængende last."],"k-signalverlust":["Radioforbindelsen til marskalen bryder sammen. Hvad laver du?","Du kan ikke se selve lastvejen.","Du fortsætter bevægelsen langsomt.","Du svinger eksperimentelt i den forrige retning.","Du stopper bevægelsen, indtil der er en klar, sikker forståelse.","Hvis der er mangel på kommunikation, fortsætter forvirrende lastbevægelse muligvis ikke."],"k-haken":["Sikkerhedskrogen lukker ikke pålideligt. Hvad er rigtigt?","Ved inspektionen bemærkes en defekt lukning.","Fejlen skal rettes professionelt inden videre brug.","Du binder låsen fast med et kabelbinder.","Du bruger kun krogen til let belastning.","Defekte sikringsanordninger på lastkroge kan føre til, at slynger løsnes og skal udbedres."],"k-zugrichtung":["Hvad er vigtigt for den lodrette støtte af en last?","Byrden skal løftes fra en maskine.","Krankrogen skal være justeret over lastens tyngdepunkt.","Krogen skal placeres så sidelæns som muligt.","Lasten skal skubbes før løft.","En kraftpåvirkning, der er så lodret som muligt over lastcentret, undgår utilladelige sidekræfter og ukontrolleret udsving."],"k-wartung":["En usædvanlig slibelyd bemærkes på kranen. Hvordan griber du det an?","Støjen opstår ved løft.","Dæk over støjen gennem højere hastighed.","Stop driften sikkert, rapporter fejl og få dem afklaret.","Fortsæt med at arbejde uden varsel indtil pausen.","Mærkbare ændringer kan indikere sikkerhedsrelevante skader og kræver en inspektion."],"k-absetzen":["Hvad skal der garanteres ved sænkning af en kranlast?","En tung last er placeret på en overflade.","Lasten kan ligge usikret på en skrå overflade.","Slynger fjernes, mens den stadig flyder.","Lasten er stabil og sikret mod at vælte eller rulle væk.","Byrden må først frigøres fra slyngegrejet, efter at den er sikkert sat ned og stabiliteten er etableret."],"l-schwerpunkt":["Hvorfor skal tyngdepunktet kendes før man slår?","En asymmetrisk formet maskine skal transporteres.","Så lasten forbliver så afbalanceret som muligt ved løft.","Så sejlene kan vælges så lange som det ønskes.","Så den tilladte bæreevne ikke spiller nogen rolle.","Tyngdepunktets placering påvirker lastfordelingen og sikker balance ved løft."],"l-etikett":["En løftestrop har ikke en læsbar bæreevnemærkat. Hvad er rigtigt?","Mærkningen er blevet uigenkendelig.","Estimer belastningskapaciteten baseret på farven.","Brug ikke løftestroppen, før dens egnethed er tydeligt påvist.","Brug kun selen én gang til små belastninger.","Passende markeringer er påkrævet for sejl; Uforklarlig bæreevne udelukker sikkert valg."],"l-kantenschutz":["Et tekstilbånd ligger over en skarp stålkant. Hvad er nødvendigt?","Lasten har skarpe kanter.","Træk båndet så stramt som muligt uden beskyttelse.","Udfør slaget hurtigere.","Brug egnet kantbeskyttelse eller andet egnet slyngeudstyr.","Skarpe kanter kan beskadige eller skære tekstilslynger; passende beskyttelse er påkrævet."],"l-spreizwinkel":["Hvordan påvirker en større hældningsvinkel belastningen på sejl?","En byrde løftes ved hjælp af to skråtstillede reb.","Ved mindre gunstige vinkler kan kræfterne i strengene øges.","Trådkræfterne forsvinder.","Vinklen har ingen indflydelse på belastningen.","Med en mindre gunstig stopvinkel kan kræfterne pr. streng øges; Belastningskapacitetstabeller skal overholdes."],"l-knoten":["Kan et slyngetov afkortes som ønsket med en knude?","Rebet er for langt til den planlagte belastning.","Ja, en stram knude forbedrer belastningskapaciteten.","Nej, brug kun godkendte afkortnings- og forankringsmetoder.","Ja, hvis knuden er fastgjort med tape.","Utilladelige knuder svækker slynger og ændrer deres tilladte bæreevne."],"l-zeichen":["Hvad gælder for kommunikationen med den person, der betjener kranen?","Lastvejen er delvist skjult.","Flere mennesker giver forskellige signaler på samme tid.","Der anvendes klare, forud aftalte signaler.","Kommunikation er aldrig påkrævet med radiokraner.","Tydelige skilte og klare ansvar forhindrer farlige forkerte bevægelser."],"l-sichtpruefung":["Hvornår skal sejl kontrolleres for synlige fejl?","Du vil bruge en slyngekæde.","Før brug skal du være opmærksom på eventuelle udvendige synlige skader.","Kun hvis der allerede er sket en ulykke.","Kun én gang ved første køb.","Før hver brug skal den sikre arbejdstilstand vurderes; Synlige skader udelukker sikker brug."],"l-drehung":["En løftet byrde begynder at rotere ukontrolleret. Hvad laver du?","Lasten bevæger sig i lastbanen.","Du lægger hånden mellem læsset og væggen.","Du placerer dig selv under byrden og holder fast i den.","Du holder afstand og lader bevægelsen stoppe kontrolleret.","Ukontrollerede lastbevægelser skaber fare for knusning og stød; Folk skal forlade fareområdet."],"l-ablegen":["Hvornår kan sejl fjernes fra læsset?","Byrden placeres på bukke.","Hvis lasten er stabil og sikret mod at vælte eller rulle væk.","Så snart den rører jorden for første gang, uanset dens position.","Mens du stadig svæver for at spare tid.","Sejl må kun fjernes, efter at de er sat sikkert og stabilt ned."],"l-ketten":["En kædeslynge har et stærkt bøjet led. Hvad laver du?","Skaden er synlig allerede før løft.","Pak det beskadigede område med tråd.","Tag kæden ud af brug og få den tjekket professionelt.","Hæv kun lasten halvt så højt.","Deformerede kædeled er synlige skader, der kan forhindre sikker brug."],"b-einweiser":["Hvad er vigtigt, når udsynet fra gravemaskinen er begrænset?","En del af bygningen skjuler køreområdet.","Passende visuelle foranstaltninger eller instruktion og klar kommunikation.","Bare pas på emhætten.","Kør gennem drejeområdet på trods af at det er usynligt.","Hvis sigtbarheden er begrænset, skal farer forhindres gennem yderligere organisatoriske og tekniske foranstaltninger."],"b-aushub":["Hvor kan udgravet materiale opbevares i nærheden af ​​en byggegrube?","Kanten af ​​brønden må ikke udsættes for yderligere risiko.","Pil op direkte på kanten, så indkørsler forbliver frie.","Opbevares i tilstrækkelig sikker afstand og i henhold til byggepladsens specifikationer.","Anbring på løs støtte uden yderligere test.","Udgravet materiale kan bringe volde og forstøving i fare på grund af yderligere belastninger; Sikkerhedsafstande skal overholdes."],"b-personen":["Må folk blive i gyngeområdet, mens gravemaskinen bevæger sig?","En person ønsker at måle under panorering.","Ja, så længe hun har sikkerhedshjelm på.","Ja, hvis gravemaskinen svinger langsomt.","Nej, fareområdet skal være frit før bevægelse.","Der er risiko for alvorlige klem- og stødskader i drejeområdet; området skal holdes frit."],"b-ladung":["Hvordan transporterer du materiale sikkert med en hjullæsser?","En fyldt skovl skal køres hen over gården.","Med en passende lav transportposition og fri sti.","Med hævet skovl for bedre udsyn.","Med åbne døre og kraftig styrevinkel.","En passende transportposition mindsker risikoen for at vælte og forbedrer kørestabiliteten."],"b-anbaupruefung":["Hvad kontrollerer du efter sammenkobling af et tilbehør?","En ny skovl blev påsat.","Bare renligheden af ​​lakken.","Den sikre låsning og funktion i henhold til betjeningsvejledningen.","Bare om enheden ser ens ud udefra.","Forkerte låse på lynkoblinger kan føre til utilsigtet frigivelse af tilbehør."],"b-einstieg":["Hvordan kommer du sikkert ind i gravemaskinens førerhus?","Trinene er snavsede efter regn.","Klatre op i kabinen via bommen.","Kom på larverne i ét hop.","Brug dertil beregnede trin og håndtag, og rengør snavsede trin.","Egnede stigninger og sikre holdepunkter reducerer risikoen for at glide og falde."],"b-graben":["En rendevæg viser revner og smuldrer. Hvad er rigtigt?","Du arbejder lige ved siden af ​​grøften.","Stop arbejdet og få de ansvarlige til at sikre gravegraven.","Kør blot tættere på kanten for at lukke grøften.","Uddyb renden yderligere uden beskyttelse.","Revner og jordbevægelser kan indikere ustabilitet og kræve yderligere sikkerhedsvurdering."],"b-betanken":["Hvad er du opmærksom på, når du tanker en jordflytningsmaskine?","Tanken er næsten tom.","Sikre motoren og tændkilderne i henhold til producentens anvisninger og undgå spild.","Fyld altid benzin eller diesel på i kabinen.","Ryg under tankning, når der ikke er vind.","Brand- og miljøfarer ved håndtering af brændstof kræver passende beskyttelsesforanstaltninger."],"b-laufwerk":["Hvorfor skal bælte og undervogn kontrolleres regelmæssigt?","Du bemærker usædvanlige vibrationer under kørslen.","Så maskinen kan bevæge sig hurtigere.","Fordi skader kan påvirke sikker føring og stabilitet.","Fordi arbejde er altid tilladt uden visuel inspektion.","Skader på drevet kan påvirke manøvredygtighed, stabilitet og sikker drift."],"b-einweisen":["Hvad kræves der ved arbejde i nærheden af ​​offentlig fodgængertrafik?","En gravemaskine arbejder direkte på kanten af ​​et fortov.","Fodgængere skal selv bevæge sig gennem gyngeområdet.","Sæt bare et skilt på skovlen.","Afspær effektivt fareområdet og diriger trafikken sikkert.","Tredjemand må ikke gå ind i farezonen for jordflytningsmaskiner; Passende barrierer og trafikdirigering er nødvendige."],"g2-fahrweg":["Der er spildt væske på vejen foran. Hvordan griber du det an?","Gaffeltrucken ville køre direkte over det glatte område.","Hold op med at køre, og få farestedet sikret eller fjernet.","Kør over stedet så hurtigt som muligt med løftet gaffel.","Håber på tørrere dæk og kør videre uændret.","Forurenede ruter bringer stabiliteten i fare og skal sikres tilstrækkeligt, før de køres på dem."],"g2-sichtladung":["En høj palle spærrer for udsynet. Hvad er rigtigt?","Du skal køre til et lagerområde og kan ikke se ruten.","Løft pallen op, indtil du kan se nedenunder den.","Kør kun med passende, sikre metoder, såsom at bakke med frit udsyn.","Du kan stadig køre på vejen uden et vejskilt eller frit udsyn.","Kørselsretningen og sigtbarheden skal muliggøre sikker observation af trafikvejen; Belastninger må ikke erstatte visuel inspektion."],"g2-fussgaengerstop":["En fodgænger stopper lige ved siden af ​​gaffeltrucken. Hvad laver du?","Personen befinder sig inden for det mulige køre- og svingområde.","Overhal fodgængeren ved at accelerere kortvarigt.","Kør forbi personen med løftet læs.","Stop og fortsæt kun i sikker afstand.","Folk skal holde sig ude af fareområdet; Om nødvendigt skal rejsen afbrydes."],"g2-hubmast":["Du bemærker en beskadiget hydraulikledning på masten. Hvad gælder?","Hydraulikolie lækker synligt fra redskabet.","Tag gaffeltrucken ud af drift og meld skaden.","Tjek lækagen med hånden, mens du løfter.","Løft kun mindre læs, indtil skiftet er overstået.","Hydrauliske skader kan føre til ukontrollerede bevægelser; sikker brug er ikke garanteret før testen."],"g2-lagerregal":["Du ønsker at opbevare en palle på en hylde. Hvad tjekker du først?","Hyldeniveauet er højt, og bæreevnen skal opretholdes.","Skub pallen ned på hylden så hurtigt som muligt.","Tjek hylderummet, lastvægten og ledig opbevaringsplads for egnethed.","Estimer den samlede vægt udelukkende baseret på antallet af kasser.","Hylder og lastbærende udstyr skal passe til last- og opbevaringssituationen."],"g2-batterieschaden":["Et gaffeltruckbatteri er beskadiget udvendigt. Hvad er rigtigt?","Før læsning bemærkes revner eller usædvanlig væske.","Dæk skader med klæbende tape og fyld med det samme.","Lad en anden person oplade batteriet uden at tjekke det.","Oplad eller brug ikke og informer de ansvarlige specialister.","Beskadigede batterier udgør elektriske og kemiske farer og kræver professionel vurdering."],"g2-fahrerkabine":["Hvad gælder for løse genstande i førerområdet?","Værktøj er på gulvet ved siden af ​​kontrolpedalerne.","Fjern genstande og hold betjeningsområdet frit.","Hold kun værktøjet med en fod under kørslen.","Skjul løse dele under førersædet.","Løse genstande kan blokere pedalerne og forringe sikker betjening af køretøjet."],"g2-uebergabe":["Du overtager en gaffeltruck efter et vagtskifte. Hvad omfatter det?","En kollega brugte sidst køretøjet.","Antag, at kollegaen har overtaget alle kontroller.","Foretag det nødvendige eftersyn og forhør om kendte mangler.","Start rejsen uden at se på maskinen.","Den, der overtager, skal inden brug sikre sig, at den er i forsvarlig stand."],"g2-transportsicherung":["En høj genstand er løs på pallen. Hvordan handler du?","Lasten kan vælte fremad under bremsning.","Bær gaflen særligt højt, så lasten forbliver stabil.","Bare tag kurverne langsomt, gå lige hurtigere.","Opstil lasten stabilt og sikre den mod at vælte eller falde.","Løse laster skal stabiliseres inden transport, så bremse- og kørebevægelser ikke får dem til at falde."],"g2-arbeitsende":["Hvad er vigtigt med en uovervåget gaffeltruck?","Du afslutter dit skift og forlader området.","Parker køretøjet sikkert og sørg for at det ikke ruller væk og uautoriseret brug.","Lad nøglen blive siddende, så kollegaerne kan finde maskinen.","Lad gaflen stå i øjenhøjde, så den er synlig.","Sikker parkering omfatter sænket lasthåndtering og beskyttelse mod bevægelse og uautoriseret idriftsættelse."],"g2-bremsweg":["Hvorfor skal du være særlig opmærksom på bremselængden under belastning?","Gaffeltrucken transporterer tungt gods gennem en lagergang.","Brems altid senere med tung last end uden last.","Juster hastigheden til sigtbarheden, jorden og belastningsforholdene.","Ved opbremsning hæves lasten kraftigt for at bremse bedre.","Masse og vejforhold påvirker bremselængden; tilpasset hastighed er nøglen."],"g2-rampe":["Hvad tjekker du, før du bestiger en stejl rampe?","Ruten kan være for stejl til køretøjet.","Kør på rampen med maksimal hastighed uanset stigningen.","Kør over kanten af ​​rampen med lasten hævet.","Kontroller den tilladte hældning og sikker driftstilstand ud fra køretøjets specifikationer.","Kun ramper inden for de tilsigtede driftsgrænser må anvendes; Betjeningsvejledning og laststyring er afgørende."],"g2-zinke":["En palle er bredere end gaffelafstanden. Hvad skal der tages hensyn til?","Du planlægger at påtage dig en usædvanlig stor belastning.","Juster gaffelafstanden og monteringspunkterne, så de passer til belastningen.","Brug kun én tand, hvis lasten er for bred.","Hæv lasten i en vinkel, indtil den når den korrekte position.","Jævn og passende belastningsoptagelse reducerer glidning og tipning."],"g2-betriebsanweisung":["Hvilken rolle spiller operationel trafikregulering?","Afmærkede ensretnings- og fodgængerarealer gælder på lageret.","For gaffeltrucks gælder kun reglerne for offentlig vej.","Følg de angivne ruter og trafikregler.","Ignorer markeringerne, når køretøjet er læsset.","Virksomhedens ruter og sikkerhedsregler beskytter gaffeltrucktrafik og folk til fods."],"g2-nothalt":["Styretøjet reagerer usædvanligt under kørsel. Hvad er rigtigt?","Køretøjet kan ikke længere styres som normalt.","Kør ved højere hastigheder for at gøre styringen mere responsiv.","Udlign fejlen med særligt store styreudslag.","Stop et sikkert sted og få bilen tjekket.","Forringet styring bringer sikker styring i fare; maskinen må ikke blive ved med at køre ukontrolleret."],"g2-anschlagkette":["Du ønsker at flytte en frithængende last med en gaffeltruck. Hvad gælder?","Et læs skal hænge på en krog under gaflerne.","Kun med godkendt apparat og egnet lastbærende udstyr.","Enhver kæde vil klare sig, hvis belastningen ikke er tung.","Spænd kæden direkte mellem begge gafler.","Frit hængende læs ændrer stabiliteten; Fabrikantens godkendelser og passende faciliteter er påkrævet."],"g2-rollenlast":["En cylindrisk komponent ligger usikret på en palle. Hvad laver du?","Lasten kan rulle under transport.","Nærmer dig pallen særligt med et ryk.","Sikre komponenten mod at rulle, inden pallen afhentes.","Placer tænderne højt nok til, at komponenten ikke er synlig.","Runde eller rullende laster kræver pålidelig beskyttelse mod ændringer i position."],"g2-pruefplakette":["Hvordan ved du, om gaffeltrucken kan bruges?","Der sidder et inspektionsmærkat på maskinen.","Ethvert klistermærke erstatter altid den daglige visuelle inspektion.","Manglende frigang kan erstattes af forsigtig kørsel.","Ud over kontrol af køretøjet skal der tages hensyn til gyldig teststatus og driftsgodkendelse.","Tilbagevendende test og daglige driftskontroller opfylder forskellige sikkerhedsfunktioner."],"g2-licht":["Belysningen på lageret gik pludselig ud. Hvad er rigtigt?","Du kan ikke længere sikkert se forhindringer på stien.","Stop kørslen, indtil sikker udsyn er garanteret.","Øg kørehastigheden for at forlade det mørke område.","Fortsæt med at køre med gaflerne hævet uden visuel inspektion.","En rute, der ikke sikkert kan overses, må ikke køres uden effektive sikkerhedsforanstaltninger."],"g2-ueberhang":["En last strækker sig langt ud over siden af ​​gaffelen. Hvad tjekker du?","Du ønsker at transportere pallen gennem en smal port.","Kompenser for den laterale projektion med en hurtig kurve.","Vurder frigang, stabilitet og tilladt lastkapacitet før kørsel.","Kør lasten med maksimal hastighed uanset dens form.","Udhæng øger kollisionsrisikoen og kan ændre stabiliteten og den nødvendige trafikplads."],"g2-wartungsbereich":["Der er barrierer foran et vedligeholdelsesområde. Hvordan opfører du dig?","Din sædvanlige rute er midlertidigt lukket.","Flyt kortvarigt barrierer og kør ubemærket igennem.","Kør direkte gennem arbejdsområdet under belastning.","Overhold lukningen og vælg en godkendt alternativ rute.","Afspærrede områder må ikke betrædes eller gennemkøres uden tilladelse."],"g2-bremsprobe":["Hvornår giver en funktionstest af driftsbremsen mening?","Du klargør gaffeltrucken inden arbejde.","Som en del af den påkrævede inspektion før brug.","Udfør kun efter en alvorlig ulykke.","Kun hvis lastbilen allerede har nået høj hastighed.","Funktionaliteten af ​​sikkerhedsrelevante faciliteter kontrolleres før brug."],"g2-fahrzeuganhaenger":["Du vil trække en trailer med en gaffeltruck. Hvad kræves der?","Virksomheden planlægger transport med påsat læs.","Bind hver trailer til en gaffel uden at tjekke.","Overhold producentens godkendelse, passende kobling og tilladt trækbelastning.","Øg blot dæktrykket og kør afsted.","Togdrift er kun mulig sikkert inden for de tekniske specifikationer og med en passende forbindelse."],"g2-rueckfahrt":["Hvad er vigtigt, når man bakker med gaffeltrucken?","Der er et forvirrende område i lagergangen.","Se altid kun i bakspejlet, uanset omgivelserne.","Kør uden udsyn, så længe der er trykket på hornet én gang.","Overhold sikkert ruten og folks område og få dem om nødvendigt instrueret.","Bakning kræver frit udsyn eller effektive yderligere sikkerhedsforanstaltninger."],"g2-lastentnahme":["Du tager en palle ud af en høj hylde. Hvad er rigtigt?","Paletten er muligvis ikke centreret.","Saml lasten sikkert op og stabiliser den før sænkning.","Lad pallen svinge til siden, når du trækker den ud.","Tjek under den hævede palle for at se, om den er beskadiget.","Kontrolleret løft og sænkning forhindrer last i at falde og farlige bevægelser."],"h2-absenkweg":["Hvorfor skal området under en arbejdsplatform forblive frit?","Kurven sænkes og materialer lægges nedenunder.","Tryk materialer ned med kurven.","Hold kun øje med operatørens fodområde.","Undgå risiko for klemning og kollision ved sænkning.","Sænkningsområdet må ikke indeholde personer eller forhindringer, der kan komme i klemme."],"h2-transporthoehe":["Hvordan flytter man en mobil scene over en lav passage?","Afstanden er lavere end den forlængede bom.","Placer platformen i en passende transportposition i henhold til betjeningsvejledningen.","Lad bommen være udstrakt og bevæg dig under loftet.","Tryk kurven mod siden af ​​dørkarmen.","For kørebevægelser skal den samlede højde og transportposition svare til producentens specifikationer og passagen."],"h2-bodenoeffnung":["Der er en usikret åbning i gulvet ved siden af ​​scenen. Hvordan reagerer du?","Et køre- eller støttepunkt er placeret nær åbningen.","Placer en støtte direkte på kanten af ​​åbningen.","Skift installationssted eller få belastningskapaciteten og sikringen kontrolleret professionelt.","Dæk kun farepunktet med en papkasse.","Åbninger og kantområder kan svigte under støttebelastninger og skal tages effektivt i betragtning."],"h2-rettungsperson":["Hvorfor skal en anden person være bekendt med redningsproceduren?","En operatør kan blive uarbejdsdygtig i toppen.","Så arbejdet i kurven generelt kan foregå uden sikkerhed.","Så scenen kan betjenes hurtigere end tilladt.","Så en sikker redning kan igangsættes i en nødsituation.","Et redningskoncept skal tage højde for jordbaseret assistance i tilfælde af fejl eller nødsituation."],"h2-werkzeugabwurf":["Hvad gælder for værktøj i stor højde?","Et løst værktøj kan falde ud over kanten af ​​kurven.","Sikre værktøj, så det ikke bringer nogen i fare eller falder ned.","Du skal blot placere værktøj på rækværket for at reducere belastningen.","Smid eventuelt værktøj ned fra kurven.","Nedfaldende genstande bringer folk i fare; Materiale skal opbevares sikkert."],"h2-trittstufe":["En kasse skal tjene som ekstra ståplads i kurven. Hvad er rigtigt?","Ellers når du kun knapt til arbejdspladsen.","Placer kassen på rækværket og klatre op på den.","Klatre ikke på improviserede forhøjninger; Brug egnet arbejdsudstyr.","Fyld kurven med vilje ud over den tilladte højde.","Improviserede forhøjninger forringer den påtænkte faldsikring og er ikke tilladt."],"h2-lastverteilen":["Hvad er du opmærksom på, når der er flere personer i arbejdskurven?","To personer arbejder i kurven med tungt værktøj.","Vurder belastningen udelukkende ud fra værktøjets størrelse.","Opbevar tungt værktøj direkte på det beskyttende rækværk.","Overskrid ikke den tilladte kurvebelastning inklusive personer og værktøj.","Den tilladte bæreevne omfatter alle personer, materialer og værktøj i kurven."],"h2-abstuetzplatte":["Hvornår overvejes yderligere shims til understøtninger?","Installationsgulvet kan kun bære en begrænset belastning.","Hvis dette er nødvendigt for sikker lastfordeling i henhold til specifikationerne.","For at placere understøtningerne så tæt som muligt på kanten af ​​en byggegrube.","For at bruge længere rækkevidde uden producentoplysninger.","Tilstrækkelige kontaktarealer er nødvendige for sikre støttestyrker."],"h2-baugrube":["En scene bør placeres direkte ved kanten af ​​en byggegrube. Hvad tjekker du?","Undergrunden kunne give efter sideværts på grund af gravegraven.","Forlæng støtterne ind i udgravningsgraven.","Sørg for tilstrækkelig sikkerhedsafstand og undergrundens bæreevne.","Kompenser kun for risikoen ved at løfte kurven langsomt.","Gravegruber kan påvirke stabiliteten på grund af fald og undergrundsbrud."],"h2-witterung":["Ising sætter sig under brug. Hvordan handler du?","Kontrolflader og arbejdsområde bliver glatte.","Hæv scenen for at undgå sne og is.","Ignorer advarslerne, så længe platformen er tændt.","Afbryd arbejdet og revurder driftsforholdene i henhold til betjeningsvejledningen.","Ændringer i vejret kan ændre ansvar, funktionalitet og sikre grænser for brug."],"h2-aufbaukontakt":["En stålkonstruktion begrænser kurvens vej. Hvad er vigtigt?","Ved løft er der risiko for klemning mellem kurven og holderen.","Planlæg bevægelser, så din krop og kurv ikke bliver fanget.","Gør rejsen hurtigere, så kurven går hurtigere forbi.","Skub konstruktionen med kurven til siden.","Klempunkter mellem platformen og omgivelserne kræver omhyggelig observation og kontrolleret bevægelse."],"h2-sicherheitsabstand":["Hvornår skal en scenes fareområde afspærres?","En offentlig transportrute passerer under stedet.","Kun hvis en genstand allerede er faldet.","Hvis tredjemand kan blive truet af bevægelse eller faldende genstande.","Aldrig, da arbejdskurven som udgangspunkt forhindrer alle farer.","Området under og ved siden af ​​scenen skal beskyttes mod forudsigelige farer."],"h2-korbtor":["Hvad gælder for indgangsdøren til arbejdskurven?","Du er allerede i arbejdshøjde.","Lad døren stå åben, så du kan komme hurtigere ud.","Bind døren permanent åben med et reb.","Hold døren lukket i henhold til den medfølgende låsemekanisme.","De medfølgende låse er en del af beskyttelsesforanstaltningerne mod at falde ned fra arbejdskurven."],"h2-energieleitung":["Hvad gælder, hvis en luftledning ikke er sikkert frakoblet?","Du arbejder med en arbejdsplatform i nærheden af ​​dem.","Sørg for specificerede sikkerhedsafstande og nødvendige beskyttelsesforanstaltninger.","Flyt kurven lige foran linjen, så længe den ikke røres.","Stol på plastikdækkene og arbejd uden huller.","Elektriske blink er også mulige uden direkte kontakt; Sikkerhedsafstande er påkrævet."],"h2-schwanken":["Arbejdskurven begynder at svinge usædvanligt kraftigt. Hvad er rigtigt?","Bevægelsen er ikke længere kontrolleret.","Juster ukontrolleret med hurtige modbevægelser.","Stop bevægelsen og kontroller årsagen eller driftsforholdene.","Tilføj ekstra personer til kurven for at gøre den tungere.","Usædvanlige vibrationer kan indikere uegnede driftsforhold eller en funktionsfejl."],"h2-ladegeraet":["Et ladekabel til det elektrisk drevne trin er beskadiget. Hvad laver du?","Ved tilslutning er beskadiget isolering synlig.","Rør ved skaden med våde handsker.","Tryk stikket ind i stikkontakten så hårdt som muligt.","Start ikke opladningsprocessen, og få kablet tjekket professionelt.","Beskadigede elektriske ledninger udgør en risiko for elektrisk stød og brand."],"h2-gelaenderanbau":["Kan du selv fjerne et gelænder for at komme tættere på?","En komponent forhindrer folk i at nærme sig arbejdsstedet.","Du må ikke ændre eller fjerne beskyttelsesanordninger på egen hånd.","Efter løftning skrues rækværket af og monteres senere.","Fortsæt med at arbejde uden rækværk, så længe der står nogen ved siden af.","Strukturelle beskyttelsesanordninger må ikke ændres uden tilladte specifikationer og sikre udskiftningsforanstaltninger."],"h2-lastkran":["Kan platformen bruges som kran til at løfte en byrde?","Materiale skal transporteres frit hængende ved siden af ​​arbejdskurven.","Når vægten er mindre end din egen kropsvægt.","Kun hvis producenten og udstyret udtrykkeligt tillader denne særlige brug.","Du skal blot fastgøre en krog til rækværket og løfte materialet.","Lifter er ikke automatisk designet til kranarbejde eller ekstra hængende læs."],"h2-arbeitsvorbereitung":["Hvad skal der til for at forberede et nyt sted?","Du kender ikke byggepladsen endnu.","Anslå blot afstanden til nærmeste parkeringsplads.","Uanset omgivelserne skal du forlænge den helt med det samme.","Vurder farer, jordbund, trafikveje, redning og udstyrs egnethed.","En lokationsrelateret risikovurdering er en forudsætning for sikre driftsforhold."],"h2-kabelschlaufe":["Et strømkabel ligger på tværs af scenens vej. Hvad er rigtigt?","Kablet kan blive fanget under bevægelsen.","Ryd vejen og beskyt elektriske kabler mod skader.","Brug kablet med hjulene som vejtærskel.","Hæv kurven uden at kontrollere gulvarealet.","Kabler, der er kørt over eller knust, kan forårsage elektriske og mekaniske farer."],"h2-leitungsnaehe":["Hvem præciserer beskyttelsesforanstaltningerne på et elektrisk system?","Platformen skal arbejde tæt på strømførende udstyr.","Personen i kurven bestemmer udelukkende efter øje.","Inddrag ansvarlige myndigheder og implementer koordinerede beskyttelsesforanstaltninger.","Afstanden vil først blive fastsat efter arbejdet er påbegyndt.","Arbejde i nærheden af ​​elektriske systemer kræver planlagte og koordinerede beskyttelsesforanstaltninger."],"h2-funkkommunikation":["Hvorfor skal signalerne mellem gulvet og kurven være tydelige?","En person på jorden hjælper med at manøvrere.","Så flere personer kan give modstridende instruktioner på samme tid.","Så nødsænkningen kan afprøves uden instruktioner.","Så bevægelser kun udføres efter klar kommunikation.","Klar kommunikation reducerer forkerte bevægelser og kollisioner ved manøvrering."],"h2-neuebedienung":["Du skifter til en anden type scene. Hvad kræves der?","Betjeningsfunktionerne er væsentligt forskellige.","Enhedsspecifik instruktion før uafhængig brug.","Bare læser firmalogoet på enheden.","En prøvetur med kurven allerede forlænget uden instruktioner.","Kvalifikation alene erstatter ikke instruktion i den specifikke enhedstype."],"h2-steckanschluss":["Hvad skal du tjekke, før du tilslutter en oplader?","En elektrisk arbejdsplatform skal oplades.","Brug enhver stikkontakt uanset tilstand og sikring.","Kontroller passende tilslutning og ubeskadiget kabel i henhold til producentens anvisninger.","Træk jævnligt strømstikket ud under opladning.","Egnede og intakte elektriske forbindelser beskytter mod elektrisk stød og brand."],"h2-absperrpersonal":["En person kommer ind i det afspærrede område under løftearbejde. Hvad laver du?","Du kan se en person direkte under arbejdskurven.","Fortsæt med at køre, hvis personen bærer en beskyttelseshjelm.","Slip et værktøj i deres retning som et advarselssignal.","Stop farlige bevægelser og få området ryddet.","En barriere erstatter ikke observation af fareområdet under drift."],"k2-arbeitsplanung":["Hvad skal indgå i arbejdsforberedelsen inden en kranoperation?","Belastning, placering og transportvej er endnu ikke koordineret.","Løft først den tungeste byrde uden yderligere planlægning.","Marker kun den korteste rute på hallens gulv.","Afklar på forhånd lastkapacitet, sejl, lastvej og fareområde.","En planlagt kranbevægelse kræver passende lasthåndtering, sikre ruter og koordinerede beskyttelsesforanstaltninger."],"k2-hakenposition":["Hvordan er krankrogen placeret over lasten før løft?","Fastgørelsespunkterne er under kranen.","Så lodret som muligt over tyngdepunktet ifølge stoppet.","Forskyd langt til siden, så lasten svinger hurtigere ind.","I hvert fald i yderkanten af ​​lasten, uanset tyngdepunktet.","Lodret påføring af kraft og passende ankerpunkter reducerer sideværts bevægelser og ukontrollerede bevægelser."],"k2-hakengabel":["En lastkrog viser en mærkbar deformation. Hvad gælder?","Krogen virker bøjet fra sin sædvanlige tilstand.","Bøj deformationen tilbage med næste belastning.","Stop krandriften og få krogen kontrolleret af en ekspert.","Tilslut kun lette belastninger og fortsæt med at arbejde.","Deformation kan påvirke krogens sikkerhed; uautoriseret videre brug er ikke tilladt."],"k2-zugueberlast":["Byrden er tungere end først antaget. Hvad laver du?","Ny vægtinformation opstår under forberedelsen.","Udskift sikkerhedsreserven med hurtigere løft.","Ignorer lastvægten ved at fastgøre den til et andet punkt.","Bestem den faktiske belastning, og kontroller belastningsgrænserne igen.","Sikker løft kræver pålidelige lastdata og overholdelse af alle relevante lastkapaciteter."],"k2-arbeitskorb":["Kan en almindelig krankrog nemt transportere mennesker?","En person ønsker at komme til en høj arbejdsplads.","Nej, persontransport kræver tilladte særlige faciliteter og foranstaltninger.","Ja, hvis personen holder fast i slyngetovet.","Ja, så snart slagtilfældet udføres særligt langsomt.","Transport af personer er kun tilladt under særlige betingelser, der er fastsat til dette formål."],"k2-bruecke":["En brokran bevæger sig ad en fælles halsti. Hvad er vigtigt?","Medarbejderne holder sig under transportvejen.","Kør med læsset lige over medarbejdernes hoveder.","Hold effektivt lastruten og trafikområdet frit og sikkert.","Brug kun advarselshornet i stedet for yderligere foranstaltninger.","Personer i fare må ikke befinde sig under hængende last eller på deres transportvej."],"k2-zweitekrane":["To kraner arbejder i et overlappende område. Hvad er nødvendigt?","Bomme eller last kan kollidere med hinanden.","Begge kranførere arbejder samtidig uden forudgående aftale.","Bevægelser accelereres bevidst for at undgå kryds.","Koordinere operationer og træffe passende foranstaltninger for at forhindre gensidige trusler.","Overlappende arbejdsområder kræver en koordineret operationel organisation og passende sikkerhedsforanstaltninger."],"k2-pruefbuch":["Hvad er betydningen af ​​det obligatoriske tilbagevendende kraneftersyn?","Maskinen bruges regelmæssigt i drift.","Den supplerer driftskontrollen med den foreskrevne ekspertundersøgelse.","Den erstatter permanent enhver visuel inspektion før arbejdet påbegyndes.","Det er kun påkrævet efter et nedbrud.","Tilbagevendende inspektioner og løbende driftskontroller har forskellige opgaver."],"k2-absetzflaeche":["Det påtænkte placeringsområde er ujævnt. Hvordan handler du?","Lasten kan vælte, når den placeres.","Placer læsset i det ene hjørne og lad det hænge uændret.","Forbered egnede, bærende og stabile underlag eller overflader.","Placer én person under lasten, mens du sænker.","Placeringsområder skal understøtte lasten sikkert og forhindre farlige vælte- eller rullebevægelser."],"k2-anfahrbereich":["Inden kranen begynder at bevæge sig, er der én person i rejseområdet. Hvad laver du?","Ruten er spærret af en person.","Skub personen til side med en kort prøvetur.","Kør af med endestopkontakten alene uden visuel inspektion.","Start kun bevægelse, når fareområdet er frit og sikkert.","Kørende og svingende bevægelser må ikke bringe mennesker i fare."],"k2-schlaffseil":["Hvorfor skal hejsetovet ikke blive ukontrolleret slapt, når det sættes ned?","Belastningen er på, krogen sænkes yderligere.","Så reb og kroge ikke kommer i klemme eller udsættes for ukontrolleret belastning.","Således at byrden derefter kan trækkes sideværts af rebet.","Så slynger løsner sig fra krogen.","Ukontrolleret kabelføring kan føre til sammenfiltringer og farlige lastbevægelser."],"k2-pendel":["En last, der transporteres, begynder at svaje. Hvad er rigtigt?","Lasten bevæger sig mere sideværts end planlagt.","Kompenser med hurtige modbevægelser og fuld fart.","Reducer bevægelser på en kontrolleret måde og ro på pendling uden personer i fareområdet.","Hold den svingende byrde med dine bare hænder.","Oscillerende belastninger kan påvirke mennesker og faciliteter; rolige bevægelser reducerer risikoen."],"k2-funkakku":["Radiostyringen af ​​en kran har et svagt batteri. Hvad gælder?","Forbindelsen kan gå i stykker under løft.","Løft en last hurtigt, før styringen svigter.","Hvis forbindelsen afbrydes, flyttes lasten ved at trække i sejlet.","Sørg for en pålidelig kontrolforbindelse før brug.","Pålidelig kontrol og kommunikation er en forudsætning for kontrollerede kranbevægelser."],"k2-mehrereanschlaeger":["To personer giver forskellige signaler til kranføreren på samme tid. Hvad er rigtigt?","Tegnene modsiger hinanden.","Afbryd bevægelse og tydeliggør tydeligt ansvar.","Foretrækker personens tegn længere væk.","Fortsæt bevægelsen efter din egen følelse.","Kranførere har brug for klar og utvetydig kommunikation, især når lastruterne er forvirrende."],"k2-endabschaltung":["Hvorfor skal en endestop ikke misbruges som en normal slagbegrænsning?","Lasten flyttes ofte op til den maksimale løfteafstand.","Grænseafbrydere tillader generelt hurtigere løft uden udsyn.","Endeafbrydere er sikkerhedsanordninger og erstatter ikke kontrolleret drift.","De skal rammes så hårdt som muligt ved hvert slag.","Sikkerhedsanordninger tjener til at beskytte mod farer og må ikke overanvendes som planlagt."],"k2-wetterbeobachtung":["Vinden tiltager markant ved stor arealbelastning. Hvad kræves der?","Et stort komponentområde fungerer som et sejl.","Hæv altid belastningen højere, så vinden har mindre effekt.","Udskift slyngene med tyndere.","Vurder vind- og driftsgrænser og juster løft om nødvendigt.","Vind kan generere betydelige yderligere kræfter og pendulbevægelser, især ved store belastninger."],"k2-ortswechsel":["Hvad er vigtigt, når man flytter en mobilkran til et nyt sted?","Undergrunds- og støtteforhold ændres.","Kontroller stativets placering og støtte, før du samler lasten op igen.","Anvend indstillingerne fra den forrige placering uden at kontrollere.","Få støtten efterjusteret under løft.","Hvert installationssted kan have forskellige jord- og støttebelastningsforhold."],"k2-betriebsbereich":["En kran skal arbejde på tværs af en gade. Hvad skal afklares?","Tredjemand kan komme ind i fareområdet.","Sikre kun vejen med et advarselshorn.","Nødvendige nedlukninger, afstemninger og beskyttelsesforanstaltninger foran navet.","Løft lasten over køretøjer så hurtigt som muligt uden at sikre den.","Sikker trafikstyring forhindrer unødig risiko for tredjemand fra last og kranbevægelser."],"k2-hochheben":["Efter testløftet hænger et læs tydeligt skævt. Hvad er rigtigt?","Fokus var tilsyneladende fejlbedømt.","Fortsæt med at løfte, så ubalancen retter sig.","Få én person til at trække den skæve last.","Sæt lasten sikkert ned, og kontroller redskabet og tyngdepunktet igen.","Testliften bruges til at opdage forkert fastgørelse og ustabile lastpositioner før transport."],"k2-schwebelast":["Kan du lade en løftet last hænge uden opsyn?","Skiftet slutter, men læsset er stadig på krogen.","Nej, sænk lasten sikkert og fastgør kranen ordentligt.","Ja, hvis kranen er låst mod at flytte væk.","Ja, så længe der er et advarselsskilt på jorden.","I princippet bør ophængte laster ikke efterlades uden opsyn."],"k2-mitnahme":["En kollega vil køre på et kranlæs. Hvad gælder?","Lasten skal transporteres til et højere punkt.","Ridning er tilladt, hvis kollegaen bærer hjelm.","Personer må ikke transporteres på eller fastgøres til normal last.","En tur er altid tilladt, så længe kollegaen er kendt af kranføreren.","At bære mennesker med last skaber betydelig risiko for at falde og knuse."],"k2-warnsignal":["Et operationelt advarselssystem på kranen svigter. Hvad er rigtigt?","Det er ikke længere muligt at give en advarsel inden afkørsel.","Ignorer systemet, når motoren kører.","Udskift advarslen permanent ved at banke på huset.","Rapportér en sikkerhedsrelevant fejl, og afbryd driften i henhold til instruktionerne.","Nødvendige advarselsanordninger skal være funktionelle, så mennesker er beskyttet rettidigt."],"k2-schneekante":["En mobilkran skal understøttes på frossen, ujævn jord. Hvad gælder?","Jorden kan miste sin bæreevne, når den tøer op.","Vurder bæreevnen og støttesituationen under faktiske forhold.","Frosset jord har altid nogen bæreevne.","Placer kun støtter på små sten.","Temperatur, luftfugtighed og undergrundsstruktur påvirker kranens bæreevne."],"k2-laufkatze":["En vogn bevæger sig mod en forhindring. Hvordan handler du?","Der er en genstand i køreområdet.","Skub langsomt genstanden væk med lasten.","Stop bevægelsen i god tid og få forhindringen fjernet sikkert.","Kør forbi forhindringen med øget hastighed.","Kranbevægelser skal styres på en sådan måde, at der ikke opstår kollisioner med forhindringer."],"k2-anschlagaufnahme":["Du bør samle en last op ved hjælp af et ikke-designet øje. Hvad er rigtigt?","Øsken kunne kun være beregnet til montering af et låg.","Hvert øje er velegnet til fuld kranbelastning.","Læg kun øjet med to personer på samme tid.","Kontroller belastningskapaciteten og egnetheden af ​​ankerpunktet før brug.","Ikke alle eksisterende øjer er et stabilt fastgørelsespunkt for kranbelastninger."],"l2-seilbruch":["Et ståltov viser flere knækkede individuelle ledninger. Hvad er rigtigt?","Brudpunkterne er i det bærende tovområde.","Fortsæt ikke med at bruge løftegrej og få det professionelt vurderet.","Bøj trådenderne tilbage med dine bare hænder.","Fortsæt med at bruge rebet, hvis belastningen er særlig let.","Trådbrud kan være et kasseringskriterium; Beskadigede reb skal vurderes fagligt."],"l2-schaekel":["Hvad er afgørende, når du bruger en bøjle?","En bøjle forbinder sejlet og lasten.","Udskift bolten med ethvert søm.","Tjek for passende belastningskapacitet, ubeskadiget tilstand og korrekte bolte.","Estimer belastningskapaciteten baseret på farven.","Sjækler skal være af passende størrelse, anvendes fuldstændigt og i den tilsigtede belastningsretning."],"l2-tragfaehigkeit":["Hvad skal du overveje, når du bruger flere tråde?","Trådene løber i en vinkel i forhold til lodret.","Du skal blot tilføje belastningskapaciteten for hver streng som ønsket.","Hæng kun byrden på den letteste tråd.","Tag højde for bæreevnen for hele ankertypen og vinkel.","Hældningsvinklen og det effektive antal tråde har en væsentlig indflydelse på den tilladte belastning."],"l2-schweissnaht":["Kan et improviseret ankerpunkt svejses til en belastning?","Der er ingen egnede udpegede afhentningssteder for lasten.","Brug kun korrekt designede og godkendte ankerpunkter.","Enhver svejsesøm er tilstrækkelig uden testning.","Indsæt en krog gennem en åbning i metalpladen.","Ankerpunkter skal bevises at være egnede til de kræfter, der er involveret i løft."],"l2-einseitig":["En belastning er væsentligt tungere på den ene side. Hvordan griber du det an?","Tyngdepunktet ligger uden for det geometriske centrum.","Lad alle tråde være lige lange uanset tyngdepunktet.","Bestem tyngdepunktet og juster positionen i overensstemmelse hermed.","Løft først lasten til fuld løftehøjde.","Hvis tyngdepunktet er forskudt, kan belastninger vælte uventet, eller individuelle tråde kan blive overbelastet."],"l2-kettenriss":["Hvad gælder for en kædeslynge med synlige revner?","Der er en revne i et af kædeleddene.","Marker revnen med maling og løft den uændret.","Pak linket ind med ledning og genbrug det.","Fjern straks kæden og informer den ansvarlige person.","Revner i bærende kædeled er sikkerhedsrelevante skader og kræver nedlukning."],"l2-lastfuehrung":["Hvordan bærer man en stor byrde, når der er risiko for rotation?","Lasten kan svinge sidelæns under løft.","Brug passende styreanordninger og en sikker afstand.","Hold lasten direkte mellem dine hænder, mens du kører.","Træd ind under lasten og juster den nedefra.","Lastføring må ikke forårsage, at hænder eller kroppe kommer ind i fareområdet."],"l2-schnueren":["Hvad er vigtigt, når du sætter snørebåndene på?","Sejlet føres rundt om en komponent.","Antag den samme belastningskapacitet som enhver anden type anker.","Vær opmærksom på egnetheden af ​​redskabstypen og den tilladte belastning i henhold til mærkningen.","Træk slyngegrejet sammen i nogen grad uden at kontrollere.","Snørebeslagets type kan ændre den tilladte bæreevne og skal bruges korrekt."],"l2-winkelmesser":["Hvorfor kan du ikke ignorere en flad strengvinkel?","To slyngeliner løber næsten vandret til lasten.","En flad vinkel gør automatisk tråden stærkere.","Belastningen er altid ligeligt fordelt uanset vinklen.","Høje strengkræfter kan overskride den tilladte belastningskapacitet.","Når vinklen til lodret øges, øges spændingerne på strengene."],"l2-heisse-last":["Hvad skal du tjekke for en varm belastning?","En ståldel er for nylig blevet varmebehandlet.","Overhold sejlens temperaturgrænser og passende valg.","Enhver tekstilslynge kan modstå enhver temperatur.","Mærkningen er ligegyldig, når den er varm.","Temperaturen kan påvirke den tilladte bæreevne af sejl."],"l2-abstand":["Kan du lægge fingrene under belastningen, når du sætter den ned?","Lasten skal lande på en overflade med millimeter præcision.","Ja, hvis du bruger arbejdshandsker.","Nej, hold afstand og brug passende hjælpemidler.","Ja, hvis kranbevægelsen er særlig langsom.","Dele af kroppen mellem lasten og underlaget kan blive fanget."],"l2-verbindung":["Et forbindelsesled på sejlkæden er ikke låst. Hvad gælder?","Beslaget mangler.","Brug bolten uden lås, når ingen ser på.","Forsegl elementet med klæbende tape.","Slå ikke til, før fastgørelseselementet er ordentligt fastgjort.","Forbindelseselementer skal sikres fuldstændigt og i overensstemmelse med deres design."],"l2-lasthaken":["Hvad tjekker man, når man hænger på en krankrog?","Flere sejl skal føres ind i krogen.","Sørg for sikker pasform og egnethed af kroge og ophæng.","Placer slynger på spidsen af ​​krogen.","Udskift kroglåsen med et kabelbinder.","Kraften skal påføres efter hensigten i de udpegede områder."],"l2-fasern":["En løftestrop viser alvorlig ruhed og fiberskade. Hvad er rigtigt?","Støttefibre er synligt beskadiget.","Dæk skaden med en anden knude.","Adskil løftestroppen og få den kontrolleret af en specialist.","Løft derefter lasten hurtigere.","Beskadigede bærende fibre kan reducere en løftestrops bæreevne betydeligt."],"l2-anheben":["Hvad gælder umiddelbart efter den første centimeters løft?","Byrden løfter sig lige af sin base.","Træk lasten til sin fulde højde uden kontrol.","Kontroller under belastningen, om sejlene er spændte.","Kontroller stoppositionen, balance og bevægelsesadfærd.","Et kontrolleret testløft gør mulige ustabiliteter synlige før videre transport."],"l2-lastgewichte":["Lastvægten er ukendt. Hvad er rigtigt?","Komponenten har ingen vægtmærkning.","Bestem den læsbare vægt, før du vælger sejl.","Estimer vægten ud fra farven på lasten.","Brug enhver dobbelt længde sejl.","Uden en kendt eller pålideligt bestemt vægt kan sejlernes egnethed ikke kontrolleres med sikkerhed."],"l2-lose-teile":["Der er løst værktøj på lasten, der skal løftes. Hvad laver du?","Værktøj kan falde ned under løft.","Hold værktøj med den ene hånd, når du kører.","Fjern eller fastgør effektivt løse genstande før løft.","Hæv lasten lidt hurtigere, så intet glider.","Løse genstande kan falde ned og bringe personer i området i fare."],"l2-wind":["En stor last er fastgjort i kraftig vind. Hvad gælder?","Komponenten giver vinden en stor overflade at angribe.","Hæv lasten uden at overveje svajende bevægelser.","Yderligere personer bør holde lasten direkte.","Vurder vindforholdene og undlad at løfte, hvis situationen er usikker.","Vindstyrker kan påvirke lastføring og stabilitet under transport."],"l2-unterlage":["Hvorfor er passende dokumenter vigtige ved fravænning?","En rund last ville rulle væk på jorden.","Sæt lasten godt ned, og sørg for at sikre den mod at rulle om nødvendigt.","Lad lasten stå direkte på sejlene.","Skub først dokumenterne under lasten, når de er blevet lagt ned.","Egnede støtter forhindrer væltning og uønskede bevægelser ved nedstilling."],"l2-transportweg":["Hvad skal koordineres, før læsset transporteres?","Lasten flyttes over flere arbejdsområder.","Kun den forventede varighed af navet.","Sikker lastvej, kommunikation og nødvendige barrierer.","Én person skal vise vej under lasten.","Transport af last kræver sikre trafikveje og klar koordinering."],"l2-schutzschlauch":["Hvad skal du være opmærksom på, når du bruger sejl med beskyttelsesslange?","Et bånd ligger mod en ru kant.","Enhver tynd klud erstatter passende kantbeskyttelse.","En beskyttelsesslange fjerner enhver tilladt belastningsgrænse.","Vælg beskyttelsesudstyr efter egnethed og anvendelseskrav.","Beskyttelsesudstyr skal passe til materialet, kanten og den påtænkte belastning."],"l2-reinigung":["En løftestrop var forurenet med et ukendt kemikalie. Hvad er rigtigt?","Båndet kan ikke længere vurderes klart.","Stop brugen og klargør kompatibilitet eller tilstand professionelt.","Rengør med eventuelt opløsningsmiddel og fortsæt med at løfte med det samme.","Ignorer kemikaliet, mens tapen er tør.","Kemikalier kan påvirke styrken af ​​tekstilslynger."],"l2-aufhaengung":["Hvad tjekker du for flere tråde på ophængsleddet?","To tråde placeres sammen i en suspension.","En tråd kan bevæge sig ind i spidsen af ​​krogen efter eget ønske.","Alle forbindelseselementer skal være egnede og arrangeret efter hensigten.","En ring med revne kan bruges til små belastninger.","Stop- og forbindelseselementer skal være bærende og korrekt anbragt."],"l2-einweiserrolle":["Hvad gælder, hvis angriberen og kranføreren ikke har nogen sigtelinje?","En transportør spærrer for udsynet til droppunktet.","Koordiner ved at ringe til flere personer uden ansvar.","Flyt lasten baseret på støj uden instruktion.","Organiser klar, sikker kommunikation og stop den, hvis den er uklar.","Manglende synlighed skal kompenseres for ved effektiv koordinering og sikker kommunikation."],"l2-ausserbetrieb":["En beskadiget slynge blev ordnet. Hvad er ellers vigtigt?","Det forbliver frit tilgængeligt sammen med ressourcer, der er klar til brug.","Sikre mod yderligere utilsigtet brug og informer den ansvarlige person.","Returner produktet umærket til lageret.","Brug den kun igen, når du bærer en særlig let last.","Kasserede sejl skal være pålideligt beskyttet før videre brug."],"b2-schwenkradius":["Hvorfor er den bagerste svingradius på en gravemaskine kritisk?","Halen bevæger sig over et begrænset arbejdsområde.","Tredjemand kan blive fanget af den svingende overbygning.","Svingeradius har ingen indflydelse på personer ved siden af ​​maskinen.","Bagenden bevæger sig altid kun i kørselsretningen.","Ved drejning opstår der også et fareområde bag maskinen."],"b2-verkehrseinweiser":["Hvordan sikres en kørebevægelse, når sigtbarheden er sløret?","En gravemaskine skal manøvrere bag en forhindring.","Kør uden at se signalgiverens signaler.","Tilrettelæg om nødvendigt passende instruktion med klar kommunikation.","Sørg kun for at bakke ved at tude én gang.","Forvirrende ruter kræver effektive foranstaltninger for at forhindre kollisioner og fastklemning."],"b2-standplatz":["Hvad gælder for et gravemaskinestativ på en skråning?","Gulvet er skråt og kan være glat.","Maskinen kan strække sig så langt, som den vil, i enhver hældning.","Opstil altid gravemaskinen på et løst lag jord.","Kontroller maskinens stabilitet og driftsgrænser før brug.","Skrænthældning og undergrund har væsentlig indflydelse på stabiliteten."],"b2-oberleitung":["Hvorfor skal bommens afstand fra elledninger planlægges?","Bommen kan komme tæt på kablet, når den drejes.","Elektrisk overslag er også muligt uden direkte kontakt.","Kun spanden kan lede elektricitet, ikke bommen.","Med tør jord er enhver afstand automatisk sikker.","Brugsgrænser og beskyttelsesafstande skal afklares, før man nærmer sig elektriske anlæg."],"b2-fremdperson":["En forbipasserende kommer ind på byggepladsen i panoreringsområdet. Hvad er rigtigt?","Personen står pludselig i nærheden af ​​gravemaskinens skovl.","Løft skovlen op og sving den over personen.","Stop straks bevægelsen og få området ryddet.","Bare fortsæt med at se personen fra sidevinduet.","Personer i fareområdet må ikke udsættes for fare ved arbejdsbevægelser."],"b2-parkstellung":["Hvordan sikres en jordflytningsmaskine efter endt arbejde?","Gravemaskinen forbliver uden opsyn på byggepladsen.","Lad skeen stå på hovedhøjde.","Lad motoren køre uden opsyn.","Læg arbejdsudstyret fra dig, fastgør maskinen og forhindre uautoriseret brug.","Korrekt parkering reducerer utilsigtet bevægelse og uautoriseret adgang."],"b2-eigenlast":["Hvorfor er udstyrsgrænser afgørende, når man løfter med gravemaskine?","Et tungt læs skal samles op på bommen.","Ellers kan stabiliteten og den tilladte bæreevne overskrides.","Enhver maskine kan løfte enhver byrde, så længe skovlen passer.","Det er kun længden af ​​rebet, der afgør risikoen.","Løfte- og lastekapacitetsoplysninger afhænger af udstyret og anvendelsessituationen."],"b2-untergrundhohlraum":["Gulvet over en gammel kælder kunne være hult. Hvad laver du?","Du bør køre gravemaskinen ind i området.","Kryds stedet med maksimalt momentum.","Afklar bæreevne og mulige hulrum inden du kører videre.","Du skal blot placere en tung belastning på overfladen.","Hulrum kan kollapse under maskinens vægt og få maskinen til at styrte ned."],"b2-feuchtigkeit":["Efter kraftig regn bliver volden blød. Hvad er rigtigt?","En gravemaskine arbejder nær kanten af ​​volden.","Flyt maskinen tættere på kanten for at øge rækkevidden.","Ignorer ændringerne indtil afslutningen af ​​skiftet.","Revurder jordbunds- og stabilitetsforhold.","Fugtindtrængning kan ændre volds bæreevne og stabilitet."],"b2-bodenprobe":["Hvorfor skal rørledningsplaner kontrolleres før udgravning?","Kabler kunne løbe under den planlagte udgravning.","Så linjer kan identificeres og passende sikkerhedsforanstaltninger kan planlægges.","Så udgravningen kan udføres hurtigere, uafhængigt af tredjeparts systemer.","Fordi maskiner aldrig må bruges i nærheden af ​​kabler.","Underjordiske forsyningsledninger kræver pålidelig placeringsafklaring før gravearbejde."],"b2-maschinenzugang":["Hvad gælder ved ind- og udstigning af jordflytningsmaskinen?","Maskinen er på ujævnt terræn.","Skub hydraulikledningen ned af kabinen.","Brug dertil beregnede trin og sørg for et sikkert fodfæste.","Hop op på drejearmen, mens maskinen kører.","Sikre stigninger og passende stoppunkter reducerer risikoen for at falde og klemme."],"b2-kupplung":["Hvordan tjekker man en ny rendegraver efter montering?","Skovlen tilsluttes via lynkoblingen.","Døm kun skeen visuelt fra en større afstand.","Træd direkte under den hævede ske.","Sørg for korrekt låsning og foreskrevne kontroltrin.","Tilbehør, der er forkert låst, kan løsne sig og bringe mennesker i fare."],"b2-hydraulikwartung":["Hvorfor må hydraulikledninger ikke åbnes under tryk?","En slange skal udskiftes.","Udslip af væske kan forårsage alvorlige skader på grund af højt tryk.","Trykket forhindrer altid olie i at slippe ud.","En åben linje kan sikkert kontrolleres med dine hænder.","Højtryksvæske kan trænge ind i væv og kræver sikker trykaflastning."],"b2-fahrweg":["Du skal køre over en midlertidig byggebro. Hvad tjekker du?","Broen er kun designet til bestemte belastninger.","Om broens farve passer til maskinen.","Bæreevne og egnethed til maskinens vægt og dimensioner.","Kun om en let bil allerede har kørt på broen.","Midlertidige konstruktioner må kun anvendes inden for deres dokumenterede bæreevne."],"b2-baggertransport":["Hvad er vigtigt ved transport af en gravemaskine på en lavlæsser?","Maskinen køres til næste byggeplads.","Lad arbejdsudstyret rage løst ud over kanten.","Hold kabinedøren åben under kørslen.","Fastgør maskinen i henhold til transportspecifikationerne og kontroller læsseudstyret.","Transportlåse og passende læssefaciliteter forhindrer udskridning og fald."],"b2-schaufelfuellung":["Hvorfor må en læssemaskine ikke køre hurtigt med skovlen højt hævet?","Belastningen er tung, og underlaget er ujævnt.","Et højt tyngdepunkt kan øge risikoen for væltning og udsynsproblemer.","Skovlen stabiliserer sig automatisk ved høje hastigheder.","Skovlhøjden er irrelevant for stabiliteten.","Et hævet tyngdepunkt forværrer typisk stabiliteten ved kørsel og sving."],"b2-fussgaenger":["Hvordan opfører du dig, når du manøvrerer ved siden af ​​fodgængere?","Adgangen til byggepladsen er også en gangsti.","Brug skovlen til at lede fodgængere til siden.","Udfør kun kørebevægelsen, når området er sikkert frit og overskueligt.","Bare tut en gang og kør langsomt uden udsyn.","Køretøjs- og passagertrafikken skal være effektivt adskilt eller sikkert koordineret."],"b2-ueberlastwarnung":["Ved løft rapporterer maskinen overbelastning. Hvad laver du?","En løftet last når de tilladte grænser.","Sluk for advarslen, og fortsæt med at hæve den uændret.","Stram belastningen pludselig, mens maskinen kører.","Stop farlige bevægelser og ret lastsituationen sikkert.","Advarsler om overbelastning indikerer mulige grænseoverskridelser og stabilitetsrisici."],"b2-wasserleitung":["Under gravningen afsløres et ukendt rør. Hvad gælder?","Linjen er ikke vist i byggeplanerne.","Stop arbejdet i det berørte område og få linjen identificeret professionelt.","Prøv at flytte linen med gravemaskinens skovl.","Fortsæt med at grave direkte under stregen uden at kontrollere.","Ukendte ledninger kan forårsage elektriske, gas- eller vandfarer."],"b2-hangefahrt":["Hvordan kører man med en gravemaskine på en stejl skråning?","Den planlagte rute fører langs en skråning.","Kør på tværs af skråningen uanset producentens grænser.","Overhold maskinens tilladte hældning og foreskrevne kørestil.","Sving bommen langt ud for at balancere køretøjet.","Den tilladte hældning afhænger af maskinen, underlaget og producentens oplysninger."],"b2-schlechtebeleuchtung":["Når du arbejder i en mørk brønd, er udsynet utilstrækkeligt. Hvad er rigtigt?","Man kan næsten ikke se mennesker og forhindringer.","Øg gravehastigheden for at fuldføre operationen hurtigt.","Brug ikke lygterne, mens motoren kører.","Stop arbejdet, indtil fareområderne er tilstrækkeligt synlige.","Sikker udsyn til køre- og arbejdsområder er påkrævet for kontrollerede maskinbevægelser."],"b2-kettenverschleiss":["Ved det daglige tjek bemærkes en beskadiget larvebane. Hvad laver du?","En kædeforbindelse viser tydelige skader.","Fortsæt ikke med at bruge maskinen ukontrolleret, og rapporter eventuelle skader.","Fortsæt med at køre med høj hastighed, så kæden retter sig ud.","Arbejd kun på blødt underlag uden at kontrollere.","Skader på drevet kan forringe kontrollerbarheden og stabiliteten."],"b2-ladearbeiten":["Du læsser en lastbil med gravemaskinen. Hvad er vigtigt?","Lastbilchaufføren holder sig tæt på læssepladsen.","Sving skovlen over den ubeskyttede førerkabine.","Forhindre personer i at opholde sig i fareområdet og koordinere processer.","Begynd at indlæse uden at kommunikere med chaufføren.","Ved læsning er der fare for faldende materiale og svingende bevægelser."],"b2-arbeitsunterbrechung":["Du afbryder gravearbejdet til et møde. Hvad gælder?","Maskinen skal stå i flere minutter uden at blive betjent.","Lad den løftede skovl være en markør.","Efterlad maskinen uden opsyn med traktionsdrevet aktiveret.","Sæt redskabet sikkert ned, og sørg for at sikre maskinen mod utilsigtet brug.","Selv korte afbrydelser kræver en sikker maskintilstand."],"b2-rollmaterial":["Løst materiale kan falde ned, når det transporteres med hjullæsseren. Hvad er rigtigt?","Læsseren kører tæt på medarbejderne.","Saml læsset sikkert og vælg en sikker kørestil med en passende skovlposition.","Løft skovlen så højt som muligt, så det omkringliggende område har frit udsyn.","Saml læsset op uden at begrænse skovlfyldningen.","Løst læs, høje skovlpositioner og dårligt udsyn kan bringe mennesker og trafik i fare."]};
